fn bump(counts: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let mut m = counts;
  let n = match m.get(w) {
    Some(c) => c + 1,
    None => 1,
  };
  m.insert(w, n);
  m
}

fn flush(counts: Map<Str, Int>, word: Str) -> Map<Str, Int> {
  if word.len() == 0 { counts } else { bump(counts, word) }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?.to_str();
  let mut counts: Map<Str, Int> = Map::new();
  let mut word = "";
  for c in text.chars() {
    let lc = c.to_lowercase();
    if lc >= "a" && lc <= "z" {
      word = word + lc;
    } else {
      counts = flush(counts, word);
      word = "";
    }
  }
  counts = flush(counts, word);

  let mut pairs: List<Str> = [];
  for w in counts.keys() {
    let n = match counts.get(w) {
      Some(c) => c,
      None => 0,
    };
    pairs.push(n.to_str() + " " + w);
  }
  pairs.sort();

  let mut out: List<Str> = [];
  let mut i = 0;
  for p in pairs {
    out.push(p);
  }
  let mut ranked: List<Str> = [];
  for p in out {
    ranked.push(p);
  }
  Ok(ranked.join("\n"))
}

struct Entry { word: Str, count: Int }

fn bump(counts: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let mut m = counts;
  let n = match m.get(w) {
    Some(c) => c + 1,
    None => 1,
  };
  m.insert(w, n);
  m
}

fn flush(counts: Map<Str, Int>, word: Str) -> Map<Str, Int> {
  if word.len() == 0 { counts } else { bump(counts, word) }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?.to_str();
  let mut counts: Map<Str, Int> = Map::new();
  let mut word = "";
  for c in text.chars() {
    if c >= "A" && c <= "Z" {
      word = word + c.to_lowercase();
    } else if c >= "a" && c <= "z" {
      word = word + c;
    } else {
      counts = flush(counts, word);
      word = "";
    }
  }
  counts = flush(counts, word);

  let mut entries: List<Entry> = [];
  for w in counts.keys() {
    let cnt = match counts.get(w) {
      Some(c) => c,
      None => 0,
    };
    entries.push(Entry { word: w, count: cnt });
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.word < b.word));

  let n = if entries.len() < 5 { entries.len() } else { 5 };
  let mut out: List<Str> = [];
  for i in 0..n {
    out.push(entries[i].word + " " + entries[i].count.to_str());
  }
  Ok(out.join("\n"))
}

struct Agg { region: Str, qty: Int, cents: Int }

fn before(a: Agg, b: Agg) -> Bool {
  if a.cents != b.cents { return a.cents > b.cents; }
  a.region < b.region
}

fn money(cents: Int) -> Str {
  let neg = cents < 0;
  let a = if neg { 0 - cents } else { cents };
  let whole = a / 100;
  let frac = a % 100;
  let fs = if frac < 10 { "0" + frac.to_str() } else { frac.to_str() };
  let sign = if neg { "-" } else { "" };
  sign + whole.to_str() + "." + fs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut totals: Map<Str, Agg> = Map::new();
  let mut skipped = 0;
  let mut first = true;

  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    if line.trim().len() == 0 {
      continue;
    }
    let parts = line.split(",");
    if parts.len() != 5 {
      skipped = skipped + 1;
      continue;
    }
    let region = parts[1].trim();
    let Some(qty) = parts[3].trim().parse_int() else {
      skipped = skipped + 1;
      continue;
    };
    let Some(unit) = parts[4].trim().parse_int() else {
      skipped = skipped + 1;
      continue;
    };
    let cur = totals.get(region).unwrap_or(Agg { region: region, qty: 0, cents: 0 });
    totals.insert(region, Agg {
      region: region,
      qty: cur.qty + qty,
      cents: cur.cents + qty * unit,
    });
  }

  let mut rows: List<Agg> = [];
  for k in totals.keys() {
    if let Some(a) = totals.get(k) {
      rows.push(a);
    }
  }
  rows.sort_by(before);

  let mut out = "";
  for r in rows {
    out = out + r.region + " " + r.qty.to_str() + " " + money(r.cents) + "\n";
  }
  out = out + "skipped " + skipped.to_str() + "\n";
  Ok(out)
}

struct ErrRow { ip: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errors: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let parts = line.split("\"");
    if parts.len() != 3 { continue; }
    let ips = parts[0].split(" ");
    let ip = ips[0];
    if ip == "" { continue; }
    let words = parts[1].split(" ");
    if words.len() < 2 { continue; }
    let qs = words[1].split("?");
    let path = qs[0];
    let tail = parts[2].trim().split(" ");
    if tail.len() != 2 { continue; }
    let Some(status) = tail[0].parse_int() else { continue; };
    let mut size = 0;
    if tail[1] != "-" {
      let Some(v) = tail[1].parse_int() else { continue; };
      size = v;
    }
    let sc = statuses.get(status).unwrap_or(0);
    statuses.insert(status, sc + 1);
    total = total + size;
    let pc = paths.get(path).unwrap_or(0);
    paths.insert(path, pc + 1);
    if status >= 500 && status < 600 {
      let ec = errors.get(ip).unwrap_or(0);
      errors.insert(ip, ec + 1);
    }
  }

  let mut out: List<Str> = [];
  for s in statuses.keys() {
    let c = statuses.get(s).unwrap_or(0);
    out.push(s.to_str() + " " + c.to_str());
  }
  out.push("bytes " + total.to_str());

  let mut top_path = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > top_n {
      top_n = c;
      top_path = p;
    }
  }
  out.push("top " + top_path + " " + top_n.to_str());

  let mut rows: List<ErrRow> = [];
  for ip in errors.keys() {
    rows.push(ErrRow { ip: ip, n: errors.get(ip).unwrap_or(0) });
  }
  rows.sort_by(|a: ErrRow, b: ErrRow| a.n > b.n);
  for r in rows {
    out.push("errors " + r.ip + " " + r.n.to_str());
  }

  Ok(out.join("\n"))
}

fn load(input: Dir) -> Result<Json, Str> {
  let text = match input.read("orders.json") {
    Ok(b) => b.to_str(),
    Err(_) => { return Err("cannot read orders.json"); },
  };
  text.parse_json()
}

fn main(input: Dir) -> Result<Str, Str> {
  let doc = load(input)?;
  let Some(orders) = doc.as_list() else { return Err("orders.json is not an array"); };

  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut refund_n = 0;
  let mut refund_t = 0;
  let mut pend = 0;

  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let cust = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
    let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);

    let mut total = 0;
    for it in items {
      let qty = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
      let price = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
      total = total + qty * price;
    }

    if status == "paid" {
      let n = counts.get(cust).unwrap_or(0);
      counts.insert(cust, n + 1);
      let t = totals.get(cust).unwrap_or(0);
      totals.insert(cust, t + total);
    } else if status == "refunded" {
      refund_n = refund_n + 1;
      refund_t = refund_t + total;
    } else if status == "pending" {
      pend = pend + 1;
    }
  }

  let mut out: List<Str> = [];
  for c in counts.keys() {
    let n = counts.get(c).unwrap_or(0);
    let t = totals.get(c).unwrap_or(0);
    out.push(c + " " + n.to_str() + " " + t.to_str());
  }
  out.push("refunded " + refund_n.to_str() + " " + refund_t.to_str());
  out.push("pending " + pend.to_str());

  Ok(out.join("\n"))
}

fn normalize(line: Str) -> Option<Str> {
  let t = line.trim().to_lowercase();
  if t.len() == 0 { return None; }
  let parts = t.split("@");
  if parts.len() != 2 { return None; }
  let local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") { return None; }
  if domain == "gmail.com" {
    let mut l = local;
    if let Some(i) = local.find("+") {
      l = local.slice(0, i);
    }
    return Some(l.replace(".", "") + "@" + domain);
  }
  Some(local + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    match normalize(line) {
      Some(a) => { seen.insert(a, true); }
      None => { invalid += 1; }
    }
  }
  let mut out: List<Str> = [];
  for a in seen.keys() {
    out.push(a);
  }
  out.push("invalid " + invalid.to_str());
  Ok(out.join("\n"))
}

fn letter(c: Str) -> Int {
  if c == "I" { 1 } else if c == "V" { 5 } else if c == "X" { 10 } else if c == "L" { 50 } else if c == "C" { 100 } else if c == "D" { 500 } else if c == "M" { 1000 } else { 0 }
}

fn from_roman(s: Str) -> Option<Int> {
  let cs = s.chars();
  if cs.len() == 0 { return None; }
  let mut total = 0;
  let mut i = 0;
  while i < cs.len() {
    let v = letter(cs[i]);
    if v == 0 { return None; }
    if i + 1 < cs.len() && v < letter(cs[i + 1]) {
      total = total - v;
    } else {
      total = total + v;
    }
    i += 1;
  }
  Some(total)
}

fn to_roman(n: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = n;
  let mut out = "";
  let mut i = 0;
  while i < 13 {
    while r >= vals[i] {
      out = out + syms[i];
      r = r - vals[i];
    }
    i += 1;
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("numbers.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let mut shown = "invalid";
    if let Some(n) = t.parse_int() {
      if n >= 1 && n <= 3999 { shown = to_roman(n); }
    } else if let Some(n) = from_roman(t) {
      if n >= 1 && n <= 3999 && to_roman(n) == t { shown = n.to_str(); }
    }
    out.push(t + " = " + shown);
  }
  Ok(out.join("\n"))
}

fn closer(opener: Str) -> Str {
  if opener == "(" { ")" } else if opener == "[" { "]" } else { "}" }
}

fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for c in line.chars() {
    col = col + 1;
    if c == "(" || c == "[" || c == "{" {
      stack.push(c);
    } else if c == ")" || c == "]" || c == "}" {
      match stack.pop() {
        None => {
          return "col " + col.to_str() + ": unexpected " + c;
        }
        Some(opener) => {
          let want = closer(opener);
          if want != c {
            return "col " + col.to_str() + ": expected " + want + ", found " + c;
          }
        }
      }
    }
  }
  match stack.pop() {
    None => "ok",
    Some(opener) => "unclosed " + closer(opener),
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("snippets.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

struct Group { method: Str, path: Str, times: List<Int> }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: List<Group> = [];
  for line in text.lines() {
    let fields = line.split(" ");
    if fields.len() != 3 { continue; }
    let Some(ms) = fields[2].parse_int() else { continue; };
    let mut idx = groups.len();
    for i in 0..groups.len() {
      if groups[i].method == fields[0] && groups[i].path == fields[1] {
        idx = i;
        break;
      }
    }
    if idx == groups.len() {
      groups.push(Group { method: fields[0], path: fields[1], times: [ms] });
    } else {
      groups[idx].times.push(ms);
    }
  }
  groups.sort_by(|a, b| a.method < b.method || (a.method == b.method && a.path < b.path));
  let mut out: List<Str> = [];
  for g in groups {
    let mut ts = g.times;
    ts.sort();
    let n = ts.len();
    let p50 = ts[(50 * n + 99) / 100 - 1];
    let p95 = ts[(95 * n + 99) / 100 - 1];
    let mx = ts[n - 1];
    out.push(g.method + " " + g.path + " count=" + n.to_str() + " p50=" + p50.to_str() + " p95=" + p95.to_str() + " max=" + mx.to_str());
  }
  Ok(out.join("\n"))
}

struct Road { a: Str, b: Str, w: Int }
struct Arc { src: Str, dst: Str, w: Int }
struct Trip { a: Str, b: Str }

fn dist_from(arcs: List<Arc>, start: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  dist.insert(start, 0);
  let mut changed = true;
  while changed {
    changed = false;
    for arc in arcs {
      if let Some(ds) = dist.get(arc.src) {
        let nd = ds + arc.w;
        let better = match dist.get(arc.dst) {
          Some(dt) => nd < dt,
          None => true,
        };
        if better {
          dist.insert(arc.dst, nd);
          changed = true;
        }
      }
    }
  }
  dist
}

fn line_for(arcs: List<Arc>, trip: Trip) -> Str {
  if trip.a == trip.b {
    return trip.a + " 0";
  }
  let dist = dist_from(arcs, trip.b);
  let Some(total) = dist.get(trip.a) else {
    return trip.a + " " + trip.b + " unreachable";
  };
  let mut cur = trip.a;
  let mut dc = total;
  let mut path: List<Str> = [trip.a];
  while cur != trip.b {
    let mut best: Option<Str> = None;
    let mut best_d = 0;
    for arc in arcs {
      if arc.src == cur {
        if let Some(dn) = dist.get(arc.dst) {
          if dn + arc.w == dc {
            let better = match best {
              Some(x) => arc.dst < x,
              None => true,
            };
            if better {
              best = Some(arc.dst);
              best_d = dn;
            }
          }
        }
      }
    }
    let Some(nxt) = best else {
      return trip.a + " " + trip.b + " unreachable";
    };
    path.push(nxt);
    cur = nxt;
    dc = best_d;
  }
  path.join(" -> ") + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut roads: List<Road> = [];
  let mut trips: List<Trip> = [];
  for raw in text.lines() {
    let line = raw.replace("\t", " ").trim();
    if line == "" || line.starts_with("#") {
      continue;
    }
    let mut parts: List<Str> = [];
    for p in line.split(" ") {
      if p != "" {
        parts.push(p);
      }
    }
    if parts.len() == 4 && parts[0] == "road" {
      if let Some(w) = parts[3].parse_int() {
        roads.push(Road { a: parts[1], b: parts[2], w: w });
      }
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push(Trip { a: parts[1], b: parts[2] });
    }
  }
  let mut arcs: List<Arc> = [];
  for r in roads {
    arcs.push(Arc { src: r.a, dst: r.b, w: r.w });
    arcs.push(Arc { src: r.b, dst: r.a, w: r.w });
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(line_for(arcs, t));
  }
  Ok(out.join("\n"))
}

struct Leaf { path: Str, text: Str }

fn read_json(d: Dir, name: Str) -> Result<Json, Str> {
  let bytes = match d.read(name) {
    Ok(b) => b,
    Err(_) => { return Err("cannot read " + name); }
  };
  bytes.to_str().parse_json()
}

fn obj_of(j: Json, what: Str) -> Result<Map<Str, Json>, Str> {
  match j {
    Json::Obj(m) => Ok(m),
    _ => Err(what + " must be a JSON object"),
  }
}

// Drop null-valued keys from objects, recursively. Used when an override
// value replaces a base value wholesale, so its nulls are removed too.
fn clean(j: Json) -> Json {
  match j {
    Json::Obj(m) => {
      let mut out: Map<Str, Json> = Map::new();
      for k in m.keys() {
        let v = m.get(k).unwrap_or(Json::Null);
        match v {
          Json::Null => {}
          _ => { out.insert(k, clean(v)); }
        }
      }
      Json::Obj(out)
    }
    Json::Arr(xs) => {
      let mut out: List<Json> = [];
      for x in xs { out.push(clean(x)); }
      Json::Arr(out)
    }
    _ => j,
  }
}

fn merge_value(cur: Option<Json>, v: Json) -> Json {
  match cur {
    Some(Json::Obj(bm)) => match v {
      Json::Obj(om) => Json::Obj(merge(bm, om)),
      _ => clean(v),
    },
    _ => clean(v),
  }
}

fn merge(base: Map<Str, Json>, over: Map<Str, Json>) -> Map<Str, Json> {
  let mut out = base;
  for k in over.keys() {
    let v = over.get(k).unwrap_or(Json::Null);
    match v {
      Json::Null => {
        if out.get(k).is_some() { out.remove(k); }
      }
      _ => {
        let nv = merge_value(out.get(k), v);
        out.insert(k, nv);
      }
    }
  }
  out
}

fn child(path: Str, key: Str) -> Str {
  if path == "" { key } else { path + "." + key }
}

fn leaves(j: Json, path: Str, acc: List<Leaf>) -> List<Leaf> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Leaf { path: path, text: "{}" });
      }
      for k in m.keys() {
        let v = m.get(k).unwrap_or(Json::Null);
        out = leaves(v, child(path, k), out);
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 {
        out.push(Leaf { path: path, text: "[]" });
      }
      for i in 0..xs.len() {
        out = leaves(xs[i], child(path, i.to_str()), out);
      }
    }
    _ => {
      out.push(Leaf { path: path, text: j.to_json() });
    }
  }
  out
}

fn main(input: Dir) -> Result<Str, Str> {
  let base_json = read_json(input, "base.json")?;
  let over_json = read_json(input, "override.json")?;
  let base = obj_of(base_json, "base.json")?;
  let over = obj_of(over_json, "override.json")?;
  let merged = Json::Obj(merge(base, over));
  let empty: List<Leaf> = [];
  let mut ls = leaves(merged, "", empty);
  ls.sort_by_key(|l| l.path);
  let mut lines: List<Str> = [];
  for l in ls {
    lines.push(l.path + "=" + l.text);
  }
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut err_text = "";
  let mut warn_text = "";
  let mut info_text = "";
  let mut error_n = 0;
  let mut warn_n = 0;
  let mut info_n = 0;
  let mut other_n = 0;
  for line in text.lines() {
    if line.trim().len() == 0 {
      continue;
    }
    let parts = line.split(" ");
    if parts.len() < 3 {
      other_n += 1;
      continue;
    }
    let level = parts[1].to_lowercase();
    if level == "error" {
      error_n += 1;
      err_text = err_text + line + "\n";
    } else if level == "warn" || level == "warning" {
      warn_n += 1;
      warn_text = warn_text + line + "\n";
    } else if level == "info" {
      info_n += 1;
      info_text = info_text + line + "\n";
    } else {
      other_n += 1;
    }
  }
  out.write("error.log", err_text.to_bytes())?;
  out.write("warn.log", warn_text.to_bytes())?;
  out.write("info.log", info_text.to_bytes())?;
  Ok("error " + error_n.to_str() + "\nwarn " + warn_n.to_str() + "\ninfo " + info_n.to_str() + "\nother " + other_n.to_str())
}

struct Entry { path: Str, bytes: Int, lines: Int }

fn join(rel: Str, name: Str) -> Str {
  if rel == "" { name } else { rel + "/" + name }
}

fn count_lines(data: Bytes) -> Int {
  let n = data.len();
  if n == 0 { return 0; }
  let mut count = 0;
  for b in data {
    if b == 10 { count += 1; }
  }
  if data[n - 1] != 10 { count += 1; }
  count
}

fn walk(d: Dir, rel: Str) -> Result<List<Entry>, IoErr> {
  let mut found: List<Entry> = [];
  let names = d.list(rel)?;
  for name in names {
    if name.ends_with("/") {
      let dir_name = name.slice(0, name.len() - 1);
      let child = join(rel, dir_name);
      let sub = walk(d, child)?;
      for e in sub {
        found.push(e);
      }
    } else {
      let path = join(rel, name);
      let data = d.read(path)?;
      found.push(Entry { path: path, bytes: data.len(), lines: count_lines(data) });
    }
  }
  Ok(found)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut entries = walk(input, "")?;
  entries.sort_by_key(|e| e.path);
  let n = entries.len();
  let mut csv: Str = "path,bytes,lines\n";
  let mut total = 0;
  for e in entries {
    total += e.bytes;
    csv = csv + e.path + "," + e.bytes.to_str() + "," + e.lines.to_str() + "\n";
  }
  out.write("index.csv", csv.to_bytes())?;
  Ok("files " + n.to_str() + " bytes " + total.to_str())
}

fn split_csv(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut in_q = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if in_q {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          in_q = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        in_q = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut seen_header = false;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    if !seen_header { seen_header = true; continue; }
    let fields = split_csv(line);
    if fields.len() != 5 { skipped += 1; continue; }
    let Some(id) = fields[0].trim().parse_int() else { skipped += 1; continue; };
    let v = fields[3].trim().to_lowercase();
    let active = v == "yes" || v == "true" || v == "1";
    let mut tags: List<Json> = [];
    for t in fields[4].split(";") {
      let tt = t.trim();
      if tt != "" { tags.push(Json::Str(tt)); }
    }
    let mut obj: Map<Str, Json> = Map::new();
    obj.insert("id", Json::Num(id));
    obj.insert("name", Json::Str(fields[1]));
    obj.insert("email", Json::Str(fields[2]));
    obj.insert("active", Json::Bool(active));
    obj.insert("tags", Json::Arr(tags));
    rows.push(Json::Obj(obj));
  }
  let n = rows.len();
  let doc = Json::Arr(rows).to_json();
  out.write("users.json", doc.to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn is_keep(c: Str) -> Bool {
  (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "."
}

fn normalize(name: Str) -> Str {
  let mut s = "";
  let mut dash = true;
  for c in name.to_lowercase().chars() {
    if is_keep(c) {
      s = s + c;
      dash = false;
    } else if !dash {
      s = s + "-";
      dash = true;
    }
  }
  if dash && s.len() > 0 {
    s = s.slice(0, s.len() - 1);
  }
  s
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: HashMap<Str, Bool> = HashMap::new();
  let mut report: List<Str> = [];
  for name in names {
    let target = normalize(name);
    if taken.get(target).is_some() {
      report.push(name + " skipped");
      continue;
    }
    taken.insert(target, true);
    let data = input.read(name)?;
    out.create(target, data)?;
    report.push(name + " -> " + target);
  }
  Ok(report.join("\n"))
}

fn part_number(name: Str) -> bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(digits) = rest.strip_suffix(".txt") else { return false; };
  if digits.len() == 0 { return false; }
  for b in digits.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn parse_part(data: Bytes) -> Option<List<Int>> {
  for b in data {
    if b > 127 { return None; }
  }
  let text = data.to_str();
  let mut out: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let Some(v) = t.parse_int() else { return None; };
    out.push(v);
  }
  Some(out)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut parts = 0;
  let mut corrupt = 0;
  let mut vals: List<Int> = [];
  for name in names {
    if !part_number(name) { continue; }
    parts += 1;
    let data = match input.read(name) {
      Ok(d) => d,
      Err(_) => {
        corrupt += 1;
        continue;
      }
    };
    if let Some(xs) = parse_part(data) {
      for x in xs { vals.push(x); }
    } else {
      corrupt += 1;
    }
  }
  vals.sort();
  let mut uniq: List<Int> = [];
  for v in vals {
    let n = uniq.len();
    if n == 0 || uniq[n - 1] != v { uniq.push(v); }
  }
  let count = uniq.len();
  let mut buf: Bytes = "".to_bytes();
  for v in uniq {
    buf.extend(v.to_str().to_bytes());
    buf.push(10);
  }
  out.write("merged.txt", buf)?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + count.to_str())
}

