fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let mut names = src.list("")?;
  names.sort();
  let dst_names = dst.list("")?;
  let mut lines: List<Str> = [];
  for name in names {
    let data = src.read(name)?;
    if dst.exists(name)? {
      let old = dst.read(name)?;
      if old == data {
        lines.push("same " + name);
      } else {
        dst.write(name, data)?;
        lines.push("updated " + name);
      }
    } else {
      dst.write(name, data)?;
      lines.push("added " + name);
    }
  }
  let mut kept = 0;
  for name in dst_names {
    if !names.contains(name) {
      kept = kept + 1;
    }
  }
  lines.push("kept " + kept.to_str());
  Ok(lines.join("\n"))
}

struct Row { page: Str, total: Int }

fn io_err(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "visits.txt not found",
    IoErr::Denied => "input denied",
    IoErr::TooLarge => "visits.txt too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "unexpected existing path",
  }
}

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "counts: too large",
    KvErr::Full => "counts: full",
    KvErr::NotInt => "counts: stored value is not a number",
    KvErr::Overflow => "counts: overflow",
  }
}

fn count_visits(text: Str) -> Map<Str, Int> {
  let mut m: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let page = line.trim();
    if page.len() == 0 { continue; }
    let n = match m.get(page) {
      Some(c) => c + 1,
      None => 1,
    };
    m.insert(page, n);
  }
  m
}

fn record(counts: Kv, run: Map<Str, Int>) -> Result<(), Str> {
  for page in run.keys() {
    let n = run.get(page).unwrap_or(0);
    counts.add("visits:" + page, n).map_err(kv_err)?;
  }
  Ok(())
}

fn totals(counts: Kv) -> Result<List<Row>, Str> {
  let mut rows: List<Row> = [];
  let keys = counts.keys("visits:").map_err(kv_err)?;
  for key in keys {
    let page = match key.strip_prefix("visits:") {
      Some(p) => p,
      None => continue,
    };
    let raw = counts.get(key).map_err(kv_err)?;
    let total = match raw {
      Some(b) => match b.to_str().parse_int() {
        Some(t) => t,
        None => 0,
      },
      None => 0,
    };
    rows.push(Row { page: page, total: total });
  }
  Ok(rows)
}

fn before(a: Row, b: Row) -> Bool {
  if a.total != b.total {
    return a.total > b.total;
  }
  a.page < b.page
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = input.read("visits.txt").map_err(io_err)?.to_str();
  let run = count_visits(text);
  record(counts, run)?;
  let mut rows = totals(counts)?;
  rows.sort_by(before);
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

fn key(id: Str) -> Str {
  "u:" + id
}

fn cmd_put(users: Kv, id: Str, name: Str, email: Str) -> Result<Str, KvErr> {
  users.set(key(id), (name + " " + email).to_bytes())?;
  Ok("ok " + id)
}

fn cmd_rename(users: Kv, id: Str, name: Str) -> Result<Str, KvErr> {
  match users.get(key(id))? {
    None => Ok("missing " + id),
    Some(b) => {
      let p = b.to_str().split(" ");
      users.set(key(id), (name + " " + p[1]).to_bytes())?;
      Ok("ok " + id)
    }
  }
}

fn cmd_get(users: Kv, id: Str) -> Result<Str, KvErr> {
  match users.get(key(id))? {
    None => Ok("missing " + id),
    Some(b) => {
      let p = b.to_str().split(" ");
      Ok("{\"id\":" + Json::Str(id).to_json()
         + ",\"name\":" + Json::Str(p[0]).to_json()
         + ",\"email\":" + Json::Str(p[1]).to_json() + "}")
    }
  }
}

fn cmd_del(users: Kv, id: Str) -> Result<Str, KvErr> {
  match users.get(key(id))? {
    None => Ok("missing " + id),
    Some(_) => {
      users.delete(key(id))?;
      Ok("ok " + id)
    }
  }
}

fn cmd_count(users: Kv) -> Result<Str, KvErr> {
  let ks = users.keys("u:")?;
  Ok("count " + ks.len().to_str())
}

fn run(users: Kv, t: Str) -> Result<Str, KvErr> {
  let p = t.split(" ");
  let n = p.len();
  if p.contains("") {
    return Ok("bad " + t);
  }
  if n == 4 && p[0] == "put" {
    return cmd_put(users, p[1], p[2], p[3]);
  }
  if n == 3 && p[0] == "rename" {
    return cmd_rename(users, p[1], p[2]);
  }
  if n == 2 && p[0] == "get" {
    return cmd_get(users, p[1]);
  }
  if n == 2 && p[0] == "del" {
    return cmd_del(users, p[1]);
  }
  if n == 1 && p[0] == "count" {
    return cmd_count(users);
  }
  Ok("bad " + t)
}

fn main(input: Dir, users: Kv) -> Str {
  let text = match input.read("commands.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return "error: cannot read commands.txt",
  };
  let mut out: List<Str> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" {
      continue;
    }
    match run(users, t) {
      Ok(s) => out.push(s),
      Err(_) => out.push("error " + t),
    }
  }
  out.join("\n")
}

struct Event { id: Str, account: Str, cents: Int }

struct Acct { name: Str, cents: Int }

fn parse_event(line: Str) -> Option<Event> {
  let Ok(j) = line.parse_json() else { return None; };
  let id = j.get("id")?.as_str()?;
  let account = j.get("account")?.as_str()?;
  let cents = j.get("cents")?.as_int()?;
  Some(Event { id: id, account: account, cents: cents })
}

fn kv_msg(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv: too large",
    KvErr::Full => "kv: store full",
    KvErr::NotInt => "kv: balance is not an integer",
    KvErr::Overflow => "kv: balance overflow",
  }
}

fn apply(state: Kv, id: Str, account: Str, cents: Int) -> Result<Bool, KvErr> {
  let seen = "seen:" + id.sha256().to_hex();
  if state.get(seen)?.is_some() {
    return Ok(false);
  }
  let hash = account.sha256().to_hex();
  state.add("bal:" + hash, cents)?;
  state.set("name:" + hash, account.to_bytes())?;
  state.set(seen, "1".to_bytes())?;
  Ok(true)
}

fn read_acct(state: Kv, name_key: Str) -> Result<Option<Acct>, KvErr> {
  let hash = name_key.slice(5, name_key.len());
  let name = match state.get(name_key)? {
    Some(b) => b.to_str(),
    None => return Ok(None),
  };
  let cents = match state.get("bal:" + hash)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  Ok(Some(Acct { name: name, cents: cents }))
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let bytes = match input.read("events.jsonl") {
    Ok(b) => b,
    Err(_) => return Err("cannot read events.jsonl"),
  };
  let text = bytes.to_str();

  let mut applied = 0;
  let mut duplicate = 0;
  let mut rejected = 0;

  for line in text.lines() {
    if line.trim() == "" {
      continue;
    }
    let Some(ev) = parse_event(line) else {
      rejected += 1;
      continue;
    };
    match apply(state, ev.id, ev.account, ev.cents) {
      Ok(true) => { applied += 1; }
      Ok(false) => { duplicate += 1; }
      Err(e) => return Err(kv_msg(e)),
    }
  }

  let names = match state.keys("name:") {
    Ok(k) => k,
    Err(e) => return Err(kv_msg(e)),
  };
  let mut accts: List<Acct> = [];
  for k in names {
    match read_acct(state, k) {
      Ok(Some(a)) => { accts.push(a); }
      Ok(None) => {}
      Err(e) => return Err(kv_msg(e)),
    }
  }
  accts.sort_by_key(|a: Acct| a.name);

  let mut out = "applied " + applied.to_str() + " duplicate " + duplicate.to_str() + " rejected " + rejected.to_str();
  for a in accts {
    out = out + "\n" + a.name + " " + a.cents.to_str();
  }
  Ok(out)
}

// Fixed-window rate limiter. Each client gets 3 allowed requests per
// 60-second window (window = UNIX_SECONDS / 60). Denied requests are not
// counted. Counts live in the Kv store, so they persist across runs.

const LIMIT: Int = 3;

fn allow(limits: Kv, key: Str) -> Result<Bool, Str> {
  let n = match limits.get(key) {
    Ok(None) => 0,
    Ok(Some(b)) => b.to_str().parse_int().unwrap_or(0),
    Err(_) => return Err("kv get failed"),
  };
  if n >= LIMIT {
    return Ok(false);
  }
  match limits.add(key, 1) {
    Ok(_) => Ok(true),
    Err(_) => Err("kv add failed"),
  }
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let text = input
    .read("requests.txt")
    .map_err(|_e| "cannot read input/requests.txt")?
    .to_str();

  let mut out: List<Str> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" {
      continue;
    }
    let parts = t.split(" ");
    if parts.len() != 2 {
      continue;
    }
    let Some(secs) = parts[0].parse_int() else { continue; };
    let client = parts[1];

    let window = secs / 60;
    let key = "w" + window.to_str() + ":" + client;

    let ok = allow(limits, key)?;
    let verdict = if ok { "allow" } else { "deny" };
    out.push(secs.to_str() + " " + client + " " + verdict);
  }

  Ok(out.join("\n"))
}

struct Row { name: Str, pts: Int, played: Int }

fn ahead(a: Row, b: Row) -> Bool {
  if a.pts != b.pts { return a.pts > b.pts; }
  if a.played != b.played { return a.played < b.played; }
  a.name < b.name
}

fn add_to(board: Kv, key: Str, n: Int) -> Result<Int, Str> {
  match board.add(key, n) {
    Ok(v) => Ok(v),
    Err(_) => Err("kv write failed"),
  }
}

fn record(board: Kv, w: Str, l: Str, draw: Bool) -> Result<(), Str> {
  let win_pts = if draw { 1 } else { 3 };
  let lose_pts = if draw { 1 } else { 0 };
  add_to(board, "pts:" + w, win_pts)?;
  add_to(board, "pla:" + w, 1)?;
  add_to(board, "pts:" + l, lose_pts)?;
  add_to(board, "pla:" + l, 1)?;
  Ok(())
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let text = match input.read("games.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read games.txt"),
  };

  for line in text.lines() {
    let parts = line.trim().split(" ");
    if parts.len() == 2 {
      record(board, parts[0], parts[1], false)?;
    } else if parts.len() == 3 {
      if parts[2] == "draw" {
        record(board, parts[0], parts[1], true)?;
      }
    }
  }

  let keys = match board.keys("pts:") {
    Ok(ks) => ks,
    Err(_) => return Err("kv list failed"),
  };

  let mut rows: List<Row> = [];
  for k in keys {
    let name = k.slice(4, k.len());
    let pts = add_to(board, "pts:" + name, 0)?;
    let played = add_to(board, "pla:" + name, 0)?;
    rows.push(Row { name: name, pts: pts, played: played });
  }

  rows.sort_by(ahead);

  let mut out_lines: List<Str> = [];
  for i in 0..3 {
    if i < rows.len() {
      let r = rows[i];
      out_lines.push((i + 1).to_str() + ". " + r.name + " " + r.pts.to_str() + " " + r.played.to_str());
    }
  }

  Ok(out_lines.join("\n"))
}

struct Order { id: Int, customer: Str, product: Str, qty: Int, unit_cents: Int }

fn db_msg(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => m,
    DbErr::Constraint(m) => m,
    DbErr::Denied => "database denied the statement",
    DbErr::Busy => "database busy",
    DbErr::TooLarge => "database result too large",
  }
}

fn db_exec(shop: Db, sql: Str, params: List<SqlValue>) -> Result<Int, Str> {
  match shop.exec(sql, params) {
    Ok(n) => Ok(n),
    Err(e) => Err(db_msg(e)),
  }
}

fn db_query(shop: Db, sql: Str, params: List<SqlValue>) -> Result<List<List<SqlValue>>, Str> {
  match shop.query(sql, params) {
    Ok(rows) => Ok(rows),
    Err(e) => Err(db_msg(e)),
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn parse_order(line: Str) -> Option<Order> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let id = parts[0].trim().parse_int()?;
  let qty = parts[3].trim().parse_int()?;
  let unit = parts[4].trim().parse_int()?;
  Some(Order {
    id: id,
    customer: parts[1].trim(),
    product: parts[2].trim(),
    qty: qty,
    unit_cents: unit,
  })
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  let bytes = match input.read("orders.csv") {
    Ok(b) => b,
    Err(_) => { return Err("cannot read orders.csv"); }
  };
  let text = bytes.to_str();
  let lines = text.lines();

  db_exec(shop, "CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", [])?;

  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;

  // Line 0 is the header.
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }

    let o = match parse_order(line) {
      Some(o) => o,
      None => { rejected += 1; continue; }
    };

    let n = db_exec(shop, "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)", [SqlValue::Int(o.id), SqlValue::Text(o.customer), SqlValue::Text(o.product), SqlValue::Int(o.qty), SqlValue::Int(o.unit_cents)])?;
    if n == 1 {
      imported += 1;
    } else {
      skipped += 1;
    }
  }

  let rows = db_query(shop, "SELECT product, SUM(qty * unit_cents), COUNT(*) FROM orders GROUP BY product ORDER BY SUM(qty * unit_cents) DESC, product ASC LIMIT 3", [])?;

  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  for row in rows {
    out = out + "\n" + text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + int_of(row[2]).to_str();
  }
  Ok(out)
}

struct Cust { id: Int, name: Str, country: Str, orders: Int, revenue: Int }

struct Country { country: Str, customers: Int, orders: Int, revenue: Int, top_name: Str, top_revenue: Int }

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query("SELECT o.customer_id, o.total_cents, c.name, c.country FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01'", [])?;

  // Per customer: paid 2026 orders and revenue.
  let mut custs: Map<Int, Cust> = Map::new();
  for row in rows {
    let cid = int_of(row[0]);
    let cents = int_of(row[1]);
    let name = text_of(row[2]);
    let country = text_of(row[3]);
    let c = custs.get(cid).unwrap_or(Cust { id: cid, name: name, country: country, orders: 0, revenue: 0 });
    custs.insert(cid, Cust { id: cid, name: c.name, country: c.country, orders: c.orders + 1, revenue: c.revenue + cents });
  }

  // Per country. Customers are visited in ascending id order, so a strict
  // comparison keeps the smaller id on a revenue tie.
  let mut countries: Map<Str, Country> = Map::new();
  for cid in custs.keys() {
    let Some(c) = custs.get(cid) else { continue; };
    let cur = countries.get(c.country).unwrap_or(Country { country: c.country, customers: 0, orders: 0, revenue: 0, top_name: "", top_revenue: 0 });
    let better = cur.customers == 0 || c.revenue > cur.top_revenue;
    let mut top_name = cur.top_name;
    let mut top_revenue = cur.top_revenue;
    if better {
      top_name = c.name;
      top_revenue = c.revenue;
    }
    countries.insert(c.country, Country { country: c.country, customers: cur.customers + 1, orders: cur.orders + c.orders, revenue: cur.revenue + c.revenue, top_name: top_name, top_revenue: top_revenue });
  }

  let mut list: List<Country> = [];
  for k in countries.keys() {
    let Some(e) = countries.get(k) else { continue; };
    list.push(e);
  }
  list.sort_by(|a: Country, b: Country| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));

  let mut out = "";
  let mut total_orders = 0;
  let mut total_revenue = 0;
  for e in list {
    out = out + e.country + " customers=" + e.customers.to_str() + " orders=" + e.orders.to_str() + " revenue=" + e.revenue.to_str() + " top=" + e.top_name + "\n";
    total_orders = total_orders + e.orders;
    total_revenue = total_revenue + e.revenue;
  }
  out = out + "total orders=" + total_orders.to_str() + " revenue=" + total_revenue.to_str() + "\n";
  Ok(out)
}

struct Batch { name: Str, lines: List<Str> }

struct Move { sku: Str, delta: Int }

fn db_msg(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => m,
    DbErr::Denied => "database denied the statement",
    DbErr::Busy => "database busy",
    DbErr::TooLarge => "database result too large",
    DbErr::Constraint(m) => m,
  }
}

fn sql_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn sql_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

// Parses a trimmed line of the form "SKU +N" or "SKU -N" (N > 0).
fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ");
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  if sku.len() == 0 { return None; }
  let mut sign = 0;
  let mut digits = "";
  if let Some(r) = amt.strip_prefix("+") {
    sign = 1;
    digits = r;
  } else if let Some(r) = amt.strip_prefix("-") {
    sign = -1;
    digits = r;
  }
  if sign == 0 { return None; }
  let Some(n) = digits.parse_int() else { return None; };
  if n <= 0 { return None; }
  Some(Move { sku: sku, delta: sign * n })
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []).map_err(db_msg)?;
  stock.exec("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", []).map_err(db_msg)?;

  let mut cur: Map<Str, Int> = Map::new();
  let rows = stock.query("SELECT sku, qty FROM stock", []).map_err(db_msg)?;
  for row in rows {
    cur.insert(sql_text(row[0]), sql_int(row[1]));
  }

  let mut applied: Map<Str, Bool> = Map::new();
  let names = stock.query("SELECT name FROM applied", []).map_err(db_msg)?;
  for row in names {
    applied.insert(sql_text(row[0]), true);
  }

  let bytes = match input.read("moves.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read moves.txt"),
  };
  let text = bytes.to_str();

  let mut batches: List<Batch> = [];
  let mut have = false;
  let mut bname: Str = "";
  let mut blines: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    if let Some(name) = line.strip_prefix("batch ") {
      if have {
        batches.push(Batch { name: bname, lines: blines });
      }
      have = true;
      bname = name.trim();
      blines = [];
    } else if have {
      blines.push(line);
    }
  }
  if have {
    batches.push(Batch { name: bname, lines: blines });
  }

  let mut out: List<Str> = [];
  for b in batches {
    if applied.get(b.name).is_some() {
      out.push(b.name + " skipped");
      continue;
    }

    let mut work: Map<Str, Int> = cur;
    let mut ok = true;
    for line in b.lines {
      let Some(m) = parse_move(line) else { ok = false; break; };
      let nq = work.get(m.sku).unwrap_or(0) + m.delta;
      if nq < 0 { ok = false; break; }
      work.insert(m.sku, nq);
    }
    if !ok {
      out.push(b.name + " rejected");
      continue;
    }

    let mut sqls: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let ks = work.keys();
    for k in ks {
      let nq = work.get(k).unwrap_or(0);
      if cur.get(k).unwrap_or(0) != nq {
        sqls.push("INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
        params.push([SqlValue::Text(k), SqlValue::Int(nq)]);
      }
    }
    sqls.push("INSERT INTO applied (name) VALUES (?)");
    params.push([SqlValue::Text(b.name)]);

    let res = stock.transaction(sqls, params);
    match res {
      Ok(_) => {
        cur = work;
        applied.insert(b.name, true);
        out.push(b.name + " applied");
      }
      Err(e) => return Err(db_msg(e)),
    }
  }

  let final_keys = cur.keys();
  for k in final_keys {
    let q = cur.get(k).unwrap_or(0);
    if q != 0 {
      out.push(k + " " + q.to_str());
    }
  }

  Ok(out.join("\n"))
}

