struct Resp { status: Int, body: Str }

struct Entry { name: Str, count: Int }

fn counter_body(name: Str, count: Int) -> Str {
  "{\"name\": \"" + name + "\", \"count\": " + count.to_str() + "}"
}

fn valid_name(s: Str) -> Bool {
  if s.len() < 1 || s.len() > 32 { return false; }
  for b in s.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn hit_counter(name: Str, counts: Kv) -> Result<Resp, KvErr> {
  let n = counts.add("c/" + name, 1)?;
  Ok(Resp { status: 200, body: counter_body(name, n) })
}

fn read_count(name: Str, counts: Kv) -> Result<Int, KvErr> {
  match counts.get("c/" + name)? {
    Some(v) => Ok(v.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn get_count(name: Str, counts: Kv) -> Result<Resp, KvErr> {
  let n = read_count(name, counts)?;
  Ok(Resp { status: 200, body: counter_body(name, n) })
}

fn ranks_before(a: Entry, b: Entry) -> Bool {
  if a.count != b.count { return a.count > b.count; }
  a.name < b.name
}

fn top_counters(counts: Kv) -> Result<Resp, KvErr> {
  let mut all: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      let n = e.value.to_str().parse_int().unwrap_or(0);
      all.push(Entry { name: e.key.slice(2, e.key.len()), count: n });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  all.sort_by(ranks_before);
  let k = all.len().min(3);
  let top = all.slice(0, k);
  let mut body = "[";
  for i in 0..top.len() {
    if i > 0 { body = body + ", "; }
    body = body + counter_body(top[i].name, top[i].count);
  }
  Ok(Resp { status: 200, body: body + "]" })
}

fn route(method: Str, target: Str, counts: Kv) -> Result<Resp, KvErr> {
  if method == "GET" && target == "/top" {
    return top_counters(counts);
  }
  if method == "POST" {
    if let Some(name) = target.strip_prefix("/hit/") {
      if !valid_name(name) {
        return Ok(Resp { status: 400, body: "{\"error\": \"bad name\"}" });
      }
      return hit_counter(name, counts);
    }
  }
  if method == "GET" {
    if let Some(name) = target.strip_prefix("/count/") {
      if !valid_name(name) {
        return Ok(Resp { status: 400, body: "{\"error\": \"bad name\"}" });
      }
      return get_count(name, counts);
    }
  }
  Ok(Resp { status: 404, body: "{\"error\": \"not found\"}" })
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let r = match route(req.method(), req.target(), counts) {
    Ok(x) => x,
    Err(_) => Resp { status: 500, body: "{\"error\": \"store\"}" },
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("ok")
}

struct Todo { id: Int, title: Str, done: Bool }

struct Patch { title: Option<Str>, done: Option<Bool> }

struct Resp { status: Int, body: Str }

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
  let method = req.method();
  let target = req.target();
  let path = match target.find("?") {
    Some(i) => target.slice(0, i),
    None => target,
  };
  let query = match target.find("?") {
    Some(i) => target.slice(i + 1, target.len()),
    None => "",
  };
  match route(store, method, path, query, req.body()) {
    Ok(resp) => reply(res, resp),
    Err(_) => reply(res, err_resp(500, "store error")),
  }
}

fn route(store: Kv, method: Str, path: Str, query: Str, body: Bytes) -> Result<Resp, KvErr> {
  if path == "/todos" {
    if method == "POST" { return create(store, body); }
    if method == "GET" { return list(store, query); }
    return Ok(not_found());
  }
  if path.starts_with("/todos/") {
    let seg = path.slice(7, path.len());
    let Some(id) = seg_id(seg) else { return Ok(not_found()); };
    if method == "GET" { return show(store, id); }
    if method == "PATCH" { return update(store, id, body); }
    if method == "DELETE" { return remove(store, id); }
  }
  Ok(not_found())
}

fn create(store: Kv, body: Bytes) -> Result<Resp, KvErr> {
  let Some(title) = new_title(body) else {
    return Ok(err_resp(400, "title required"));
  };
  let id = store.add("seq", 1)?;
  let t = Todo { id: id, title: title, done: false };
  store.set(key_of(id), todo_json(t).to_bytes())?;
  Ok(Resp { status: 201, body: todo_json(t) })
}

fn list(store: Kv, query: Str) -> Result<Resp, KvErr> {
  let all = load_all(store)?;
  let mut keep: List<Todo> = [];
  for t in all {
    if query == "done=true" && !t.done { continue; }
    if query == "done=false" && t.done { continue; }
    keep.push(t);
  }
  let mut parts: List<Str> = [];
  for t in keep {
    parts.push(todo_json(t));
  }
  Ok(Resp { status: 200, body: "[" + parts.join(",") + "]" })
}

fn show(store: Kv, id: Int) -> Result<Resp, KvErr> {
  match load_one(store, id)? {
    Some(t) => Ok(Resp { status: 200, body: todo_json(t) }),
    None => Ok(not_found()),
  }
}

fn update(store: Kv, id: Int, body: Bytes) -> Result<Resp, KvErr> {
  let Some(old) = load_one(store, id)? else {
    return Ok(not_found());
  };
  let Some(p) = parse_patch(body) else {
    return Ok(err_resp(400, "bad update"));
  };
  let mut cur = old;
  if let Some(s) = p.title { cur.title = s; }
  if let Some(d) = p.done { cur.done = d; }
  store.set(key_of(id), todo_json(cur).to_bytes())?;
  Ok(Resp { status: 200, body: todo_json(cur) })
}

fn remove(store: Kv, id: Int) -> Result<Resp, KvErr> {
  match load_one(store, id)? {
    Some(_) => {
      store.delete(key_of(id))?;
      Ok(Resp { status: 204, body: "" })
    },
    None => Ok(not_found()),
  }
}

fn reply(res: Outgoing, r: Resp) -> Str {
  let headers: List<Str> = if r.body.len() == 0 { [] } else { ["content-type"] };
  let values: List<Str> = if r.body.len() == 0 { [] } else { ["application/json"] };
  let _sent = res.send(r.status, headers, values, r.body.to_bytes());
  "sent"
}

fn err_body(msg: Str) -> Str {
  "{\"error\": \"" + msg + "\"}"
}

fn err_resp(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: err_body(msg) }
}

fn not_found() -> Resp {
  err_resp(404, "not found")
}

fn seg_id(seg: Str) -> Option<Int> {
  let n = seg.parse_int()?;
  if n.to_str() == seg && n > 0 { Some(n) } else { None }
}

fn key_of(id: Int) -> Str {
  let mut s = id.to_str();
  while s.len() < 20 {
    s = "0" + s;
  }
  "todo:" + s
}

fn todo_json(t: Todo) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  let j = Json::Obj(m);
  j.to_json()
}

fn todo_of(v: Bytes) -> Option<Todo> {
  let j = v.to_str().parse_json().ok()?;
  let id = j.get("id")?.as_int()?;
  let title = j.get("title")?.as_str()?;
  let done = j.get("done")?.as_bool()?;
  Some(Todo { id: id, title: title, done: done })
}

fn load_one(store: Kv, id: Int) -> Result<Option<Todo>, KvErr> {
  let got = store.get(key_of(id))?;
  match got {
    Some(v) => Ok(todo_of(v)),
    None => Ok(None),
  }
}

fn load_all(store: Kv) -> Result<List<Todo>, KvErr> {
  let mut out: List<Todo> = [];
  let mut after: Option<Str> = None;
  let mut more = true;
  while more {
    let page = store.scan("todo:", after, 1000)?;
    let n = page.len();
    for e in page {
      if let Some(t) = todo_of(e.value) { out.push(t); }
    }
    if n < 1000 {
      more = false;
    } else {
      after = Some(page[n - 1].key);
    }
  }
  Ok(out)
}

fn utf8_ok(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  let mut ok = true;
  while i < n && ok {
    let c = b[i];
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c < 128 {
      need = 0;
    } else if c >= 194 && c <= 223 {
      need = 1;
    } else if c >= 224 && c <= 239 {
      need = 2;
      if c == 224 { lo = 160; }
      if c == 237 { hi = 159; }
    } else if c >= 240 && c <= 244 {
      need = 3;
      if c == 240 { lo = 144; }
      if c == 244 { hi = 143; }
    } else {
      ok = false;
    }
    if ok {
      if i + need >= n {
        ok = false;
      } else if need > 0 {
        let d = b[i + 1];
        if d < lo || d > hi { ok = false; }
        let mut k = 2;
        while k <= need && ok {
          let e = b[i + k];
          if e < 128 || e > 191 { ok = false; }
          k = k + 1;
        }
      }
      i = i + need + 1;
    }
  }
  ok
}

fn new_title(body: Bytes) -> Option<Str> {
  if !utf8_ok(body) { return None; }
  let j = body.to_str().parse_json().ok()?;
  let s = j.get("title")?.as_str()?.trim();
  if s.len() == 0 { None } else { Some(s) }
}

fn patch_of(j: Json) -> Option<Patch> {
  let m = j.as_map()?;
  let mut title: Option<Str> = None;
  let mut done: Option<Bool> = None;
  if let Some(v) = m.get("title") {
    let s = v.as_str()?.trim();
    if s.len() == 0 { return None; }
    title = Some(s);
  }
  if let Some(v) = m.get("done") {
    done = Some(v.as_bool()?);
  }
  Some(Patch { title: title, done: done })
}

fn parse_patch(body: Bytes) -> Option<Patch> {
  if !utf8_ok(body) { return None; }
  let j = body.to_str().parse_json().ok()?;
  patch_of(j)
}

// Notes API on SQLite: one HTTP handler, run once per request.

struct Reply { status: Int, body: Str }
struct Filter { tag: Option<Str>, q: Option<Str> }

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn err_body(msg: Str) -> Str {
  obj1("error", Json::Str(msg)).to_json()
}

fn bad() -> Reply {
  Reply { status: 400, body: err_body("invalid note") }
}

fn not_found() -> Reply {
  Reply { status: 404, body: err_body("not found") }
}

fn int_at(row: List<SqlValue>, i: Int) -> Int {
  let cell = row[i];
  if let SqlValue::Int(n) = cell { n } else { 0 }
}

fn text_at(row: List<SqlValue>, i: Int) -> Str {
  let cell = row[i];
  if let SqlValue::Text(s) = cell { s } else { "" }
}

fn schema(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS note_tags (note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE, tag TEXT NOT NULL, pos INTEGER NOT NULL, PRIMARY KEY (note_id, tag))", [])?;
  Ok(())
}

fn create(db: Db, raw: Bytes) -> Result<Reply, DbErr> {
  let j = match raw.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return Ok(bad()),
  };
  let obj = match j.as_map() {
    Some(m) => m,
    None => return Ok(bad()),
  };
  let title = match obj.get("title").and_then(|t| t.as_str()) {
    Some(t) => t,
    None => return Ok(bad()),
  };
  if title.len() == 0 {
    return Ok(bad());
  }
  let body = match obj.get("body").and_then(|b| b.as_str()) {
    Some(b) => b,
    None => return Ok(bad()),
  };
  let mut tags: List<Str> = [];
  if let Some(tv) = obj.get("tags") {
    let items = match tv.as_list() {
      Some(l) => l,
      None => return Ok(bad()),
    };
    for it in items {
      let s = match it.as_str() {
        Some(s) => s,
        None => return Ok(bad()),
      };
      let low = s.to_lowercase();
      if !tags.contains(low) {
        tags.push(low);
      }
    }
  }
  let rows = db.query(
    "INSERT INTO notes (title, body) VALUES (?, ?) RETURNING id",
    [SqlValue::Text(title), SqlValue::Text(body)])?;
  let id = int_at(rows[0], 0);
  if tags.len() > 0 {
    let mut sqls: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut pos = 0;
    for t in tags {
      sqls.push("INSERT INTO note_tags (note_id, tag, pos) VALUES (?, ?, ?)");
      params.push([SqlValue::Int(id), SqlValue::Text(t), SqlValue::Int(pos)]);
      pos += 1;
    }
    db.transaction(sqls, params)?;
  }
  Ok(Reply { status: 201, body: obj1("id", Json::Num(id)).to_json() })
}

fn get_note(db: Db, id: Int) -> Result<Reply, DbErr> {
  let rows = db.query("SELECT title, body FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 {
    return Ok(not_found());
  }
  let title = text_at(rows[0], 0);
  let body = text_at(rows[0], 1);
  let trows = db.query("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY pos", [SqlValue::Int(id)])?;
  let mut tags: List<Json> = [];
  for r in trows {
    tags.push(Json::Str(text_at(r, 0)));
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("body", Json::Str(body));
  m.insert("tags", Json::Arr(tags));
  Ok(Reply { status: 200, body: Json::Obj(m).to_json() })
}

fn list_notes(db: Db, tag: Option<Str>, q: Option<Str>) -> Result<Reply, DbErr> {
  let mut sql: Str = "SELECT id, title FROM notes WHERE 1 = 1";
  let mut params: List<SqlValue> = [];
  if let Some(t) = tag {
    sql = sql + " AND id IN (SELECT note_id FROM note_tags WHERE tag = ?)";
    params.push(SqlValue::Text(t));
  }
  if let Some(w) = q {
    sql = sql + " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
    params.push(SqlValue::Text(w));
    params.push(SqlValue::Text(w));
  }
  sql = sql + " ORDER BY id DESC";
  let rows = db.query(sql, params)?;
  let mut items: List<Json> = [];
  for r in rows {
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(int_at(r, 0)));
    m.insert("title", Json::Str(text_at(r, 1)));
    items.push(Json::Obj(m));
  }
  Ok(Reply { status: 200, body: Json::Arr(items).to_json() })
}

fn delete_note(db: Db, id: Int) -> Result<Reply, DbErr> {
  let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if n == 0 {
    return Ok(not_found());
  }
  Ok(Reply { status: 200, body: obj1("deleted", Json::Num(id)).to_json() })
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.parse_int()?;
  if n.to_str() == s { Some(n) } else { None }
}

fn parse_query(query: Str) -> Filter {
  let mut tag: Option<Str> = None;
  let mut q: Option<Str> = None;
  for part in query.split("&") {
    if let Some(i) = part.find("=") {
      let key = part.slice(0, i);
      let val = part.slice(i + 1, part.len());
      if key == "tag" {
        tag = Some(val.to_lowercase());
      }
      if key == "q" {
        q = Some(val);
      }
    }
  }
  Filter { tag: tag, q: q }
}

fn route(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  let method = req.method();
  let target = req.target();
  let mut path: Str = target;
  let mut query: Str = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let parts = path.split("/");
  let is_notes = parts.len() == 2 && parts[0] == "" && parts[1] == "notes";
  if is_notes && method == "GET" {
    let f = parse_query(query);
    return list_notes(db, f.tag, f.q);
  }
  if is_notes && method == "POST" {
    return create(db, req.body());
  }
  if parts.len() == 3 && parts[0] == "" && parts[1] == "notes" {
    let id = match parse_id(parts[2]) {
      Some(n) => n,
      None => return Ok(not_found()),
    };
    if method == "GET" {
      return get_note(db, id);
    }
    if method == "DELETE" {
      return delete_note(db, id);
    }
  }
  Ok(not_found())
}

fn handle(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  schema(db)?;
  route(req, db)
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let reply = match handle(req, db) {
    Ok(r) => r,
    Err(_) => Reply { status: 500, body: err_body("internal error") },
  };
  res.send(reply.status, ["content-type"], ["application/json"], reply.body.to_bytes())?;
  Ok("ok")
}

struct Station { id: Str, name: Str }

fn degrees(t: Int) -> Str {
  let sign = if t < 0 { "-" } else { "" };
  let a = if t < 0 { 0 - t } else { t };
  let whole = a / 10;
  let frac = a % 10;
  sign + whole.to_str() + "." + frac.to_str()
}

fn stations(api: Http) -> Option<List<Station>> {
  let bytes = api.get("/stations").ok()?;
  let j = bytes.to_str().parse_json().ok()?;
  let items = j.get("stations")?.as_list()?;
  let mut out: List<Station> = [];
  for s in items {
    let id = s.get("id")?.as_str()?;
    let name = s.get("name")?.as_str()?;
    out.push(Station { id: id, name: name });
  }
  Some(out)
}

fn readings(api: Http, id: Str) -> Option<List<Int>> {
  let bytes = api.get("/stations/" + id + "/readings").ok()?;
  let j = bytes.to_str().parse_json().ok()?;
  let items = j.get("readings")?.as_list()?;
  let mut temps: List<Int> = [];
  for r in items {
    if let Some(v) = r.get("temp").and_then(|t| t.as_int()) {
      temps.push(v);
    }
  }
  Some(temps)
}

fn summary(name: Str, temps: List<Int>) -> Str {
  if temps.len() == 0 {
    return name + " no data";
  }
  let mut lo = temps[0];
  let mut hi = temps[0];
  let mut sum = 0;
  for t in temps {
    lo = lo.min(t);
    hi = hi.max(t);
    sum = sum + t;
  }
  let n = temps.len();
  let avg = sum / n;
  name + " min=" + degrees(lo) + " max=" + degrees(hi) + " avg=" + degrees(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut list = match stations(api) {
    Some(l) => l,
    None => return Err("stations unavailable"),
  };
  list.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in list {
    match readings(api, s.id) {
      None => lines.push(s.name + " unavailable"),
      Some(temps) => lines.push(summary(s.name, temps)),
    }
  }
  Ok(lines.join("\n"))
}

struct Order { id: Int, status: Str, cents: Int, currency: Str }

fn parse_order(j: Json) -> Result<Order, Str> {
  let id = j.get("id").and_then(|x| x.as_int()).ok_or("bad order id")?;
  let status = j.get("status").and_then(|x| x.as_str()).ok_or("bad order status")?;
  let cents = j.get("cents").and_then(|x| x.as_int()).ok_or("bad order cents")?;
  let currency = j.get("currency").and_then(|x| x.as_str()).ok_or("bad order currency")?;
  Ok(Order { id: id, status: status, cents: cents, currency: currency })
}

fn get_page(api: Http, page: Int) -> Result<Json, Str> {
  let path = "/orders?page=" + page.to_str();
  let resp = match api.get(path) {
    Ok(b) => b,
    Err(_) => return Err("fetch of page " + page.to_str() + " failed"),
  };
  resp.to_str().parse_json()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut orders: List<Order> = [];
  let mut page: Int = 1;
  loop {
    let doc = get_page(api, page)?;
    let items = doc.get("orders").and_then(|j| j.as_list()).ok_or("response has no orders")?;
    for j in items {
      orders.push(parse_order(j)?);
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    let Some(n) = next else { break; };
    page = n;
  }

  let total = orders.len();
  let mut paid: Map<Str, Int> = Map::new();
  let mut refunded: Int = 0;
  let mut has_best = false;
  let mut best_id: Int = 0;
  let mut best_cents: Int = 0;
  for o in orders {
    if o.status == "paid" {
      let sum = paid.get(o.currency).unwrap_or(0);
      paid.insert(o.currency, sum + o.cents);
      if !has_best || o.cents > best_cents || (o.cents == best_cents && o.id < best_id) {
        has_best = true;
        best_id = o.id;
        best_cents = o.cents;
      }
    } else if o.status == "refunded" {
      refunded = refunded + 1;
    }
  }

  let mut cur: Map<Str, Json> = Map::new();
  for c in paid.keys() {
    cur.insert(c, Json::Num(paid.get(c).unwrap_or(0)));
  }
  let mut top: Map<Str, Json> = Map::new();
  top.insert("orders", Json::Num(total));
  top.insert("paid_cents", Json::Obj(cur));
  top.insert("refunded", Json::Num(refunded));
  if has_best {
    top.insert("largest", Json::Num(best_id));
  } else {
    top.insert("largest", Json::Null);
  }

  let payload = Json::Obj(top).to_json();
  let resp = match api.send("POST", "/summaries", ["content-type: application/json"], payload.to_bytes()) {
    Ok(r) => r,
    Err(_) => return Err("summary post failed"),
  };
  if resp.status != 201 {
    return Err("summary answered " + resp.status.to_str());
  }
  let reply = resp.body.to_str().parse_json()?;
  let id = reply.get("id").and_then(|j| j.as_str()).ok_or("summary reply has no id")?;
  Ok(id)
}

struct Entry { key: Str, value: Str }

fn lookup(items: List<Entry>, key: Str) -> Option<Str> {
  for e in items {
    if e.key == key { return Some(e.value); }
  }
  None
}

fn without(items: List<Entry>, key: Str) -> List<Entry> {
  items.filter(|e| e.key != key)
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let file = match input.read("ops.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read ops.txt"),
  };
  let all = file.to_str().lines();
  if all.len() == 0 { return Err("ops.txt is empty"); }

  let cap = all[0].strip_prefix("capacity ").and_then(|s| s.trim().parse_int());
  let Some(capacity) = cap else { return Err("line 1 must be `capacity N`"); };
  if capacity < 1 { return Err("capacity must be at least 1"); }

  let mut hits: Int = 0;
  let mut misses: Int = 0;
  let mut evictions: Int = 0;
  let mut items: List<Entry> = [];
  let mut out: Str = "";

  let stored = match cache.get("state") {
    Ok(v) => v,
    Err(_) => return Err("cannot read cache"),
  };
  if let Some(raw) = stored {
    let doc = match raw.to_str().parse_json() {
      Ok(j) => j,
      Err(e) => return Err("corrupt cache: " + e),
    };
    hits = doc.get("hits").and_then(|j| j.as_int()).unwrap_or(0);
    misses = doc.get("misses").and_then(|j| j.as_int()).unwrap_or(0);
    evictions = doc.get("evictions").and_then(|j| j.as_int()).unwrap_or(0);
    let saved = doc.get("items").and_then(|j| j.as_list()).unwrap_or([]);
    for pair in saved {
      let k = pair.at(0).and_then(|x| x.as_str()).unwrap_or("");
      let v = pair.at(1).and_then(|x| x.as_str()).unwrap_or("");
      items.push(Entry { key: k, value: v });
    }
  }

  while items.len() > capacity {
    let victim = items[0].key;
    items = items.slice(1, items.len());
    evictions += 1;
    out = out + "evict " + victim + "\n";
  }

  for i in 1..all.len() {
    let ln = i + 1;
    let line = all[i];
    if line == "" { continue; }

    let mut op = "";
    let mut key = "";
    let mut value = "";
    let mut valid = false;
    if line.starts_with("get ") || line.starts_with("del ") {
      op = line.slice(0, 3);
      key = line.slice(4, line.len());
      valid = key != "" && !key.contains(" ");
    } else if line.starts_with("put ") {
      op = "put";
      let rest = line.slice(4, line.len());
      match rest.find(" ") {
        Some(p) => {
          key = rest.slice(0, p);
          value = rest.slice(p + 1, rest.len());
          valid = key != "" && value != "";
        },
        None => {},
      }
    }

    if !valid {
      out = out + "bad line " + ln.to_str() + "\n";
      continue;
    }

    if op == "get" {
      match lookup(items, key) {
        Some(v) => {
          hits += 1;
          items = without(items, key);
          items.push(Entry { key: key, value: v });
          out = out + key + "=" + v + "\n";
        },
        None => {
          misses += 1;
          out = out + key + " miss\n";
        },
      }
    } else if op == "put" {
      let is_new = lookup(items, key).is_none();
      if is_new && items.len() >= capacity {
        let victim = items[0].key;
        items = items.slice(1, items.len());
        evictions += 1;
        out = out + "evict " + victim + "\n";
      }
      items = without(items, key);
      items.push(Entry { key: key, value: value });
    } else {
      items = without(items, key);
    }
  }

  let mut names: List<Str> = [];
  for e in items { names.push(e.key); }
  names.reverse();
  if names.len() == 0 {
    out = out + "cache:\n";
  } else {
    out = out + "cache: " + names.join(",") + "\n";
  }
  out = out + "stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + evictions.to_str() + "\n";

  let mut arr: List<Json> = [];
  for e in items {
    let mut pair: List<Json> = [];
    pair.push(Json::Str(e.key));
    pair.push(Json::Str(e.value));
    arr.push(Json::Arr(pair));
  }
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("hits", Json::Num(hits));
  obj.insert("misses", Json::Num(misses));
  obj.insert("evictions", Json::Num(evictions));
  obj.insert("items", Json::Arr(arr));
  let write_res = cache.set("state", Json::Obj(obj).to_json().to_bytes());
  if write_res.is_err() { return Err("cannot write cache"); }

  Ok(out)
}

fn as_strs(j: Json) -> Option<List<Str>> {
  let items = j.as_list()?;
  let mut out: List<Str> = [];
  for item in items {
    let s = item.as_str()?;
    out.push(s);
  }
  Some(out)
}

fn dedup(xs: List<Str>) -> List<Str> {
  let mut out: List<Str> = [];
  for x in xs {
    if !out.contains(x) {
      out.push(x);
    }
  }
  out
}

fn index_of(names: List<Str>, n: Str) -> Option<Int> {
  let mut i = 0;
  while i < names.len() {
    if names[i] == n {
      return Some(i);
    }
    i += 1;
  }
  None
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let bytes = input.read("packages.json")?;
  let Ok(doc) = bytes.to_str().parse_json() else {
    return Ok("error: not an object");
  };
  let Json::Obj(m) = doc else {
    return Ok("error: not an object");
  };

  let mut names: List<Str> = [];
  let mut dep_names: List<List<Str>> = [];
  let mut invalid: List<Str> = [];
  for k in m.keys() {
    let Some(v) = m.get(k) else { continue; };
    let Some(list) = as_strs(v) else {
      invalid.push(k);
      continue;
    };
    names.push(k);
    dep_names.push(dedup(list));
  }
  let n = names.len();

  let mut dep_ids: List<List<Int>> = [];
  let mut has_missing: List<Bool> = [];
  let mut missing: Map<Str, List<Str>> = Map::new();
  for p in 0..n {
    let ds = dep_names[p];
    let mut ids: List<Int> = [];
    let mut miss = false;
    for d in ds {
      let Some(i) = index_of(names, d) else {
        miss = true;
        let mut who: List<Str> = [];
        if let Some(l) = missing.get(d) {
          who = l;
        }
        who.push(names[p]);
        missing.insert(d, who);
        continue;
      };
      ids.push(i);
    }
    dep_ids.push(ids);
    has_missing.push(miss);
  }

  let mut stage: List<Int> = [];
  for _i in 0..n {
    stage.push(0);
  }
  let mut changed = true;
  while changed {
    changed = false;
    for p in 0..n {
      if stage[p] == 0 {
        let ds = dep_ids[p];
        let mut ok = !has_missing[p];
        let mut best = 0;
        for d in ds {
          if stage[d] == 0 {
            ok = false;
          } else if stage[d] > best {
            best = stage[d];
          }
        }
        if ok {
          stage[p] = best + 1;
          changed = true;
        }
      }
    }
  }

  let mut reach: List<List<Bool>> = [];
  for p in 0..n {
    let mut seen: List<Bool> = [];
    for _i in 0..n {
      seen.push(false);
    }
    let mut stack: List<Int> = [];
    let start = dep_ids[p];
    for d in start {
      stack.push(d);
    }
    while stack.len() > 0 {
      let Some(x) = stack.pop() else { break; };
      if !seen[x] {
        seen[x] = true;
        let nx = dep_ids[x];
        for d in nx {
          stack.push(d);
        }
      }
    }
    reach.push(seen);
  }

  let mut out: List<Str> = [];
  let mut maxs = 0;
  let mut built = 0;
  for p in 0..n {
    if stage[p] > maxs {
      maxs = stage[p];
    }
    if stage[p] > 0 {
      built += 1;
    }
  }
  let mut s = 1;
  while s <= maxs {
    let mut at: List<Str> = [];
    for p in 0..n {
      if stage[p] == s {
        at.push(names[p]);
      }
    }
    if at.len() > 0 {
      out.push("stage " + s.to_str() + ": " + at.join(", "));
    }
    s += 1;
  }

  let mut assigned: List<Bool> = [];
  for _i in 0..n {
    assigned.push(false);
  }
  for p in 0..n {
    if reach[p][p] && !assigned[p] {
      let mut g: List<Str> = [];
      for q in 0..n {
        if reach[p][q] && reach[q][p] {
          assigned[q] = true;
          g.push(names[q]);
        }
      }
      out.push("cycle: " + g.join(", "));
    }
  }

  for miss_name in missing.keys() {
    let Some(who) = missing.get(miss_name) else { continue; };
    out.push("missing: " + miss_name + " (needed by " + who.join(", ") + ")");
  }

  if invalid.len() > 0 {
    out.push("invalid: " + invalid.join(", "));
  }

  let mut blocked: List<Str> = [];
  for p in 0..n {
    if stage[p] == 0 && !reach[p][p] {
      blocked.push(names[p]);
    }
  }
  if blocked.len() > 0 {
    out.push("blocked: " + blocked.join(", "));
  }

  out.push("built " + built.to_str() + " of " + n.to_str());
  Ok(out.join("\n"))
}

struct Booking { room: Str, day: Str, start: Int, end: Int, who: Str }

struct Span { s: Int, e: Int }

const OPEN: Int = 540;
const CLOSE: Int = 1080;
const MIN_FREE: Int = 30;

fn is_digit(c: Int) -> Bool {
  c >= 48 && c <= 57
}

// "HH:MM" to minutes since midnight. "24:00" is 1440 and no other 24:MM is valid.
fn parse_time(s: Str) -> Option<Int> {
  if s.len() != 5 { return None; }
  let b = s.to_bytes();
  if b[2] != 58 { return None; }
  if !is_digit(b[0]) || !is_digit(b[1]) || !is_digit(b[3]) || !is_digit(b[4]) { return None; }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if m > 59 { return None; }
  if h == 24 && m == 0 { return Some(1440); }
  if h > 23 { return None; }
  Some(h * 60 + m)
}

fn two(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

// Always five bytes, so byte order matches time order.
fn hhmm(m: Int) -> Str {
  two(m / 60) + ":" + two(m % 60)
}

fn parse_line(line: Str) -> Option<Booking> {
  let f = line.split(",");
  if f.len() != 5 { return None; }
  let start = parse_time(f[2])?;
  let end = parse_time(f[3])?;
  if end <= start { return None; }
  Some(Booking { room: f[0], day: f[1], start: start, end: end, who: f[4] })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let ls = text.lines();

  let mut bs: List<Booking> = [];
  let mut sk: List<Str> = [];
  for i in 0..ls.len() {
    let ln = i + 1;
    let line = ls[i];
    if i == 0 { continue; }
    if line.trim().len() == 0 { continue; }
    match parse_line(line) {
      Some(b) => {
        if !bs.contains(b) { bs.push(b); }
      }
      None => sk.push(ln.to_str()),
    }
  }

  let mut rooms: List<Str> = [];
  for b in bs {
    if !rooms.contains(b.room) { rooms.push(b.room); }
  }
  rooms.sort();

  let mut lines_out: List<Str> = [];
  for r in rooms {
    let mut days: List<Str> = [];
    for b in bs {
      if b.room == r && !days.contains(b.day) { days.push(b.day); }
    }
    days.sort();

    for d in days {
      let mut ds: List<Booking> = [];
      for b in bs {
        if b.room == r && b.day == d { ds.push(b); }
      }
      ds.sort_by_key(|b| b.start);

      // Busy: merge intervals, touching ones included.
      let mut spans: List<Span> = [];
      for b in ds {
        let n = spans.len();
        if n > 0 && b.start <= spans[n - 1].e {
          let last = spans[n - 1];
          spans[n - 1] = Span { s: last.s, e: last.e.max(b.end) };
        } else {
          spans.push(Span { s: b.start, e: b.end });
        }
      }
      let mut busy_parts: List<Str> = [];
      for s in spans {
        busy_parts.push(hhmm(s.s) + "-" + hhmm(s.e));
      }
      let busy = "  busy " + busy_parts.join(", ");

      // Free: gaps of at least MIN_FREE minutes within OPEN..CLOSE.
      let mut gaps: List<Str> = [];
      let mut cur = OPEN;
      for s in spans {
        let stop = s.s.min(CLOSE);
        if stop - cur >= MIN_FREE {
          gaps.push(hhmm(cur) + "-" + hhmm(stop));
        }
        cur = cur.max(s.e);
      }
      if CLOSE - cur >= MIN_FREE {
        gaps.push(hhmm(cur) + "-" + hhmm(CLOSE));
      }
      let free = if gaps.len() == 0 { "  free none" } else { "  free " + gaps.join(", ") };

      // Conflicts: pairs overlapping by at least one minute.
      // Key = start "HH:MM" then the line, so byte order gives start, then text.
      let n = ds.len();
      let mut clashes: List<Str> = [];
      for i in 0..n {
        for j in 0..n {
          if i < j {
            let a = ds[i];
            let b = ds[j];
            let os = a.start.max(b.start);
            let oe = a.end.min(b.end);
            if oe - os >= 1 {
              let names = if a.who < b.who { a.who + "/" + b.who } else { b.who + "/" + a.who };
              let line = "  conflict " + names + " " + hhmm(os) + "-" + hhmm(oe);
              clashes.push(hhmm(os) + line);
            }
          }
        }
      }
      clashes.sort();

      lines_out.push(r + " " + d);
      lines_out.push(busy);
      lines_out.push(free);
      for c in clashes {
        lines_out.push(c.slice(5, c.len()));
      }
    }
  }

  if sk.len() == 0 {
    lines_out.push("skipped: none");
  } else {
    lines_out.push("skipped: " + sk.join(", "));
  }

  Ok(lines_out.join("\n"))
}

struct Issue { path: Str, msg: Str }

fn read_text(d: Dir, name: Str) -> Result<Str, Str> {
  match d.read(name) {
    Ok(b) => Ok(b.to_str()),
    Err(_) => Err("cannot read " + name),
  }
}

fn sfield(j: Json, key: Str) -> Option<Str> { j.get(key).and_then(|x| x.as_str()) }

fn ifield(j: Json, key: Str) -> Option<Int> { j.get(key).and_then(|x| x.as_int()) }

fn type_ok(v: Json, t: Str) -> Bool {
  match v {
    Json::Null => t == "null",
    Json::Bool(_) => t == "boolean",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Str(_) => t == "string",
    Json::Arr(_) => t == "array",
    Json::Obj(_) => t == "object",
  }
}

fn int_bound(n: Int, s: Json) -> Option<Str> {
  if let Some(lo) = ifield(s, "minimum") {
    if n < lo { return Some("less than " + lo.to_str()); }
  }
  if let Some(hi) = ifield(s, "maximum") {
    if n > hi { return Some("greater than " + hi.to_str()); }
  }
  None
}

fn float_bound(f: Float, s: Json) -> Option<Str> {
  if let Some(lo) = ifield(s, "minimum") {
    if f < lo.to_float() { return Some("less than " + lo.to_str()); }
  }
  if let Some(hi) = ifield(s, "maximum") {
    if f > hi.to_float() { return Some("greater than " + hi.to_str()); }
  }
  None
}

fn str_issue(x: Str, s: Json) -> Option<Str> {
  let len = x.chars().len();
  if let Some(lo) = ifield(s, "min_length") {
    if len < lo { return Some("shorter than " + lo.to_str()); }
  }
  if let Some(hi) = ifield(s, "max_length") {
    if len > hi { return Some("longer than " + hi.to_str()); }
  }
  if let Some(opts) = s.get("enum").and_then(|j| j.as_list()) {
    let mut found = false;
    for o in opts {
      if o.as_str() == Some(x) { found = true; }
    }
    if !found { return Some("not in enum"); }
  }
  None
}

fn check(v: Json, s: Json, path: Str) -> List<Issue> {
  let mut out: List<Issue> = [];
  let t = sfield(s, "type").unwrap_or("");
  if !type_ok(v, t) {
    out.push(Issue { path: path, msg: "expected " + t });
    return out;
  }
  match v {
    Json::Num(n) => {
      if let Some(m) = int_bound(n, s) { out.push(Issue { path: path, msg: m }); }
    }
    Json::Float(f) => {
      if let Some(m) = float_bound(f, s) { out.push(Issue { path: path, msg: m }); }
    }
    Json::Str(x) => {
      if let Some(m) = str_issue(x, s) { out.push(Issue { path: path, msg: m }); }
    }
    Json::Arr(xs) => {
      if let Some(mn) = ifield(s, "min_items") {
        if xs.len() < mn {
          out.push(Issue { path: path, msg: "fewer than " + mn.to_str() + " items" });
        }
      }
      if let Some(item) = s.get("items") {
        let mut i = 0;
        for x in xs {
          for e in check(x, item, path + "[" + i.to_str() + "]") { out.push(e); }
          i += 1;
        }
      }
    }
    Json::Obj(m) => {
      let props = s.get("properties").and_then(|j| j.as_map());
      if let Some(rs) = s.get("required").and_then(|j| j.as_list()) {
        for r in rs {
          if let Some(name) = r.as_str() {
            if m.get(name).is_none() {
              out.push(Issue { path: path + "." + name, msg: "missing required field" });
            }
          }
        }
      }
      if let Some(ps) = props {
        for k in ps.keys() {
          if let Some(val) = m.get(k) {
            if let Some(sub) = ps.get(k) {
              for e in check(val, sub, path + "." + k) { out.push(e); }
            }
          }
        }
      }
      let allow = s.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
      if !allow {
        for k in m.keys() {
          let mut known = false;
          if let Some(ps) = props {
            if ps.get(k).is_some() { known = true; }
          }
          if !known {
            out.push(Issue { path: path + "." + k, msg: "unexpected field" });
          }
        }
      }
    }
    _ => {}
  }
  out
}

fn issue_less(a: Issue, b: Issue) -> Bool {
  if a.path == b.path { return a.msg < b.msg; }
  a.path < b.path
}

fn main(input: Dir) -> Result<Str, Str> {
  let schema_text = read_text(input, "schema.json")?;
  let schema = match schema_text.parse_json() {
    Ok(j) => j,
    Err(e) => return Err("schema.json: " + e),
  };
  let records = read_text(input, "records.jsonl")?;
  let mut out: Str = "";
  let mut lineno = 0;
  let mut total = 0;
  let mut valid = 0;
  for raw in records.lines() {
    lineno += 1;
    let line = raw.trim();
    if line == "" { continue; }
    total += 1;
    let label = "line " + lineno.to_str() + ": ";
    match line.parse_json() {
      Err(_) => { out = out + label + "invalid JSON\n"; }
      Ok(v) => {
        let mut issues = check(v, schema, "$");
        if issues.len() == 0 {
          valid += 1;
          out = out + label + "ok\n";
        } else {
          issues.sort_by(issue_less);
          for iss in issues {
            out = out + label + iss.path + ": " + iss.msg + "\n";
          }
        }
      }
    }
  }
  out = out + "valid " + valid.to_str() + " of " + total.to_str();
  Ok(out)
}

struct Rec { id: Str, version: Int, line: Str }

struct Job { line: Str, version: Int, attempts: Int, outcome: Str, status: Int }

fn parse_rec(t: Str) -> Option<Rec> {
  let j = t.parse_json().ok()?;
  let id = j.get("id")?.as_str()?;
  let version = j.get("version")?.as_int()?;
  Some(Rec { id: id, version: version, line: t })
}

fn last_pushed(state: Kv, id: Str) -> Result<Option<Int>, KvErr> {
  match state.get("v/" + id)? {
    Some(b) => Ok(b.to_str().parse_int()),
    None => Ok(None),
  }
}

fn io_msg(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "file not found",
    IoErr::Denied => "access denied",
    IoErr::TooLarge => "file too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "already exists",
  }
}

fn kv_msg(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "state value too large",
    KvErr::Full => "state store full",
    KvErr::NotInt => "state value not an integer",
    KvErr::Overflow => "state counter overflow",
  }
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let bytes = input.read("records.jsonl").map_err(io_msg)?;
  let text = bytes.to_str();

  let mut report: List<Str> = [];
  let mut recs: Map<Str, Rec> = Map::new();
  let mut lineno = 0;
  for line in text.lines() {
    lineno = lineno + 1;
    let t = line.trim();
    if t.len() == 0 { continue; }
    match parse_rec(t) {
      Some(r) => { recs.insert(r.id, r); }
      None => { report.push("line " + lineno.to_str() + " invalid"); }
    }
  }

  let mut jobs: Map<Str, Job> = Map::new();
  let mut ids: List<Str> = [];
  for id in recs.keys() {
    let Some(r) = recs.get(id) else { return Err("internal error"); };
    let last = last_pushed(state, id).map_err(kv_msg)?;
    let fresh = match last { Some(v) => r.version > v, None => true };
    if fresh {
      jobs.insert(id, Job { line: r.line, version: r.version, attempts: 0, outcome: "pending", status: 0 });
      ids.push(id);
    } else {
      jobs.insert(id, Job { line: r.line, version: r.version, attempts: 0, outcome: "unchanged", status: 0 });
    }
  }

  loop {
    if ids.len() == 0 { break; }
    let mut reqs: List<HttpRequest> = [];
    for id in ids {
      let Some(j) = jobs.get(id) else { return Err("internal error"); };
      reqs.push(HttpRequest { method: "PUT", path: "/records/" + id, headers: ["content-type: application/json"], body: j.line.to_bytes(), timeout_ms: 0 });
    }
    let results = api.send_all(reqs);
    let mut next: List<Str> = [];
    for i in 0..ids.len() {
      let id = ids[i];
      let Some(j) = jobs.get(id) else { return Err("internal error"); };
      let attempts = j.attempts + 1;
      let res = results[i];
      let status = match res { Ok(resp) => resp.status, Err(_) => 0 };
      if status >= 200 && status < 300 {
        state.set("v/" + id, j.version.to_str().to_bytes()).map_err(kv_msg)?;
        jobs.insert(id, Job { outcome: "synced", attempts: attempts, ..j });
      } else if status >= 400 && status < 500 {
        jobs.insert(id, Job { outcome: "rejected", attempts: attempts, status: status, ..j });
      } else if attempts >= 3 {
        jobs.insert(id, Job { outcome: "failed", attempts: attempts, ..j });
      } else {
        jobs.insert(id, Job { attempts: attempts, ..j });
        next.push(id);
      }
    }
    ids = next;
  }

  let mut n_synced = 0;
  let mut n_unchanged = 0;
  let mut n_rejected = 0;
  let mut n_failed = 0;
  for id in jobs.keys() {
    let Some(j) = jobs.get(id) else { return Err("internal error"); };
    if j.outcome == "synced" {
      n_synced = n_synced + 1;
      report.push(id + " synced");
    } else if j.outcome == "unchanged" {
      n_unchanged = n_unchanged + 1;
      report.push(id + " unchanged");
    } else if j.outcome == "rejected" {
      n_rejected = n_rejected + 1;
      report.push(id + " rejected " + j.status.to_str());
    } else {
      n_failed = n_failed + 1;
      report.push(id + " failed");
    }
  }

  report.push("synced " + n_synced.to_str() + " unchanged " + n_unchanged.to_str() + " rejected " + n_rejected.to_str() + " failed " + n_failed.to_str());
  Ok(report.join("\n"))
}

struct Xfer {
  src: Str,
  dst: Str,
  cents: Int,
}

enum Outcome {
  Done,
  Duplicate,
  Failed(Str),
}

fn as_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn as_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn select_rows(db: Db, sql: Str, p: List<SqlValue>) -> Result<List<List<SqlValue>>, Str> {
  db.query(sql, p).map_err(|e| "database error")
}

fn exec_sql(db: Db, sql: Str, p: List<SqlValue>) -> Result<(), Str> {
  let _n: Int = db.exec(sql, p).map_err(|e| "database error")?;
  Ok(())
}

fn ddl(db: Db, sql: Str) -> Result<(), Str> {
  let empty: List<SqlValue> = [];
  exec_sql(db, sql, empty)
}

fn stamp(db: Db, ms: Int) -> Result<Str, Str> {
  let p: List<SqlValue> = [SqlValue::Int(ms / 1000)];
  let rows = select_rows(db, "SELECT strftime('%Y-%m-%dT%H:%M:%SZ', ?, 'unixepoch')", p)?;
  let v = rows[0][0];
  match v {
    SqlValue::Text(s) => Ok(s),
    _ => Err("bad time"),
  }
}

fn exists(db: Db, name: Str) -> Result<Bool, Str> {
  let p: List<SqlValue> = [SqlValue::Text(name)];
  let rows = select_rows(db, "SELECT COUNT(*) FROM accounts WHERE name = ?", p)?;
  Ok(as_int(rows[0][0]) > 0)
}

fn balance_of(db: Db, name: Str) -> Result<Option<Int>, Str> {
  let p: List<SqlValue> = [SqlValue::Text(name)];
  let rows = select_rows(db, "SELECT balance FROM accounts WHERE name = ? AND closed = 0", p)?;
  if rows.len() == 0 {
    return Ok(None);
  }
  let r = rows[0];
  Ok(Some(as_int(r[0])))
}

fn prior(db: Db, id: Str) -> Result<Option<Xfer>, Str> {
  let p: List<SqlValue> = [SqlValue::Text(id)];
  let rows = select_rows(db, "SELECT src, dst, cents FROM transfers WHERE id = ?", p)?;
  if rows.len() == 0 {
    return Ok(None);
  }
  let r = rows[0];
  Ok(Some(Xfer { src: as_text(r[0]), dst: as_text(r[1]), cents: as_int(r[2]) }))
}

fn apply(db: Db, now: Str, w: List<Str>) -> Result<Outcome, Str> {
  if w[0] == "open" {
    if w.len() != 3 {
      return Ok(Outcome::Failed("malformed"));
    }
    let cents = match w[2].parse_int() {
      Some(c) => c,
      None => return Ok(Outcome::Failed("malformed")),
    };
    if cents < 0 {
      return Ok(Outcome::Failed("bad amount"));
    }
    let name = w[1];
    if exists(db, name)? {
      return Ok(Outcome::Failed("account exists"));
    }
    let p: List<SqlValue> = [SqlValue::Text(name), SqlValue::Int(cents), SqlValue::Text(now)];
    exec_sql(db, "INSERT INTO accounts (name, balance, changed, closed) VALUES (?, ?, ?, 0)", p)?;
    return Ok(Outcome::Done);
  }

  if w[0] == "transfer" {
    if w.len() != 5 {
      return Ok(Outcome::Failed("malformed"));
    }
    let cents = match w[4].parse_int() {
      Some(c) => c,
      None => return Ok(Outcome::Failed("malformed")),
    };
    let id = w[1];
    let src = w[2];
    let dst = w[3];
    if let Some(old) = prior(db, id)? {
      if old.src == src && old.dst == dst && old.cents == cents {
        return Ok(Outcome::Duplicate);
      }
      return Ok(Outcome::Failed("id reused"));
    }
    if cents <= 0 {
      return Ok(Outcome::Failed("bad amount"));
    }
    if src == dst {
      return Ok(Outcome::Failed("same account"));
    }
    let fbal = match balance_of(db, src)? {
      Some(b) => b,
      None => return Ok(Outcome::Failed("no account " + src)),
    };
    let tbal = match balance_of(db, dst)? {
      Some(b) => b,
      None => return Ok(Outcome::Failed("no account " + dst)),
    };
    if fbal < cents {
      return Ok(Outcome::Failed("insufficient funds"));
    }
    if cents > 9223372036854775807 - tbal {
      return Ok(Outcome::Failed("overflow"));
    }
    let sql: List<Str> = [
      "UPDATE accounts SET balance = balance - ?, changed = ? WHERE name = ?",
      "UPDATE accounts SET balance = balance + ?, changed = ? WHERE name = ?",
      "INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)"
    ];
    let params: List<List<SqlValue>> = [
      [SqlValue::Int(cents), SqlValue::Text(now), SqlValue::Text(src)],
      [SqlValue::Int(cents), SqlValue::Text(now), SqlValue::Text(dst)],
      [SqlValue::Text(id), SqlValue::Text(src), SqlValue::Text(dst), SqlValue::Int(cents)]
    ];
    let _n: Int = db.transaction(sql, params).map_err(|e| "database error")?;
    return Ok(Outcome::Done);
  }

  if w[0] == "close" {
    if w.len() != 2 {
      return Ok(Outcome::Failed("malformed"));
    }
    let name = w[1];
    let bal = match balance_of(db, name)? {
      Some(b) => b,
      None => return Ok(Outcome::Failed("no account " + name)),
    };
    if bal != 0 {
      return Ok(Outcome::Failed("balance not zero"));
    }
    let p: List<SqlValue> = [SqlValue::Text(name)];
    exec_sql(db, "UPDATE accounts SET closed = 1 WHERE name = ?", p)?;
    return Ok(Outcome::Done);
  }

  Ok(Outcome::Failed("malformed"))
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  ddl(db, "CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, changed TEXT NOT NULL, closed INTEGER NOT NULL)")?;
  ddl(db, "CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)")?;

  let now = stamp(db, clock.now_ms())?;

  let raw = input.read("ops.txt").map_err(|e| "cannot read ops.txt")?;
  let text = raw.to_str();
  let lines = text.lines();

  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;

  for i in 0..lines.len() {
    let t = lines[i].trim();
    if t == "" {
      continue;
    }
    let w = t.split(" ");
    let n = i + 1;
    let res = apply(db, now, w)?;
    match res {
      Outcome::Done => {
        ok += 1;
      }
      Outcome::Duplicate => {
        dup += 1;
      }
      Outcome::Failed(msg) => {
        failed += 1;
        let line = now + " line " + n.to_str() + ": " + msg;
        log.write(line).map_err(|e| "cannot write log")?;
      }
    }
  }

  let empty: List<SqlValue> = [];
  let accts = select_rows(db, "SELECT name, balance, changed FROM accounts WHERE closed = 0 ORDER BY name", empty)?;

  let mut out: List<Str> = [];
  out.push("ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str());
  for r in accts {
    out.push(as_text(r[0]) + " " + as_int(r[1]).to_str() + " last " + as_text(r[2]));
  }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Str }

struct Creds { name: Str, password: Str }

fn reply(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: "{\"error\": \"" + msg + "\"}" }
}

fn unauthorized() -> Resp {
  reply(401, "unauthorized")
}

fn utf8_ok(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c < 128 {
      need = 0;
    } else if c >= 194 && c <= 223 {
      need = 1;
    } else if c == 224 {
      need = 2;
      lo = 160;
    } else if (c >= 225 && c <= 236) || c == 238 || c == 239 {
      need = 2;
    } else if c == 237 {
      need = 2;
      hi = 159;
    } else if c == 240 {
      need = 3;
      lo = 144;
    } else if c >= 241 && c <= 243 {
      need = 3;
    } else if c == 244 {
      need = 3;
      hi = 143;
    } else {
      return false;
    }
    let mut k = 1;
    while k <= need {
      let j = i + k;
      if j >= n {
        return false;
      }
      let x = b[j];
      let mut l = 128;
      let mut h = 191;
      if k == 1 {
        l = lo;
        h = hi;
      }
      if x < l || x > h {
        return false;
      }
      k += 1;
    }
    i = i + need + 1;
  }
  true
}

fn valid_name(s: Str) -> Bool {
  let n = s.len();
  if n < 3 || n > 20 {
    return false;
  }
  for c in s.to_bytes() {
    let ok = (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 95;
    if !ok {
      return false;
    }
  }
  true
}

fn parse_obj(req: Incoming) -> Option<Json> {
  let b = req.body();
  if !utf8_ok(b) {
    return None;
  }
  b.to_str().parse_json().ok()
}

fn field(j: Json, key: Str) -> Option<Str> {
  j.get(key).and_then(|v| v.as_str())
}

fn read_creds(req: Incoming) -> Option<Creds> {
  let j = parse_obj(req)?;
  let name = field(j, "name")?;
  let password = field(j, "password")?;
  Some(Creds { name: name, password: password })
}

fn read_int(store: Kv, key: Str) -> Result<Int, KvErr> {
  let v = store.get(key)?;
  match v {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn bearer(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  let mut i = 0;
  while i < names.len() {
    if names[i] == "authorization" {
      return values[i].strip_prefix("Bearer ");
    }
    i += 1;
  }
  None
}

fn session(store: Kv, token: Str, now: Int) -> Result<Option<Str>, KvErr> {
  if token.len() != 32 {
    return Ok(None);
  }
  let exp = match store.get("x:" + token)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  if now >= exp {
    return Ok(None);
  }
  let nm = store.get("s:" + token)?;
  match nm {
    Some(b) => Ok(Some(b.to_str())),
    None => Ok(None),
  }
}

fn create_user(req: Incoming, store: Kv) -> Result<Resp, KvErr> {
  let c = match read_creds(req) {
    Some(c) => c,
    None => return Ok(reply(400, "invalid")),
  };
  if !valid_name(c.name) || c.password.len() < 8 {
    return Ok(reply(400, "invalid"));
  }
  let hash = c.password.sha256();
  let created = store.swap("p:" + c.name, None, Some(hash))?;
  if !created {
    return Ok(reply(409, "name taken"));
  }
  Ok(Resp { status: 201, body: "{\"name\": \"" + c.name + "\"}" })
}

fn login(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let c = match read_creds(req) {
    Some(c) => c,
    None => return Ok(reply(401, "bad credentials")),
  };
  if !valid_name(c.name) {
    return Ok(reply(401, "bad credentials"));
  }
  let stored = store.get("p:" + c.name)?;
  let hash = match stored {
    Some(h) => h,
    None => return Ok(reply(401, "bad credentials")),
  };
  let now = clock.now_ms();
  let locked_until = read_int(store, "l:" + c.name)?;
  if now < locked_until {
    return Ok(reply(429, "locked"));
  }
  if hash.ct_eq(c.password.sha256()) {
    store.delete("f:" + c.name)?;
    store.add("n:" + c.name, 1)?;
    let token = rng.bytes(16).to_hex();
    store.set("s:" + token, c.name.to_bytes())?;
    store.set("x:" + token, (now + 1800000).to_str().to_bytes())?;
    return Ok(Resp {
      status: 200,
      body: "{\"token\": \"" + token + "\", \"expires_in\": 1800}",
    });
  }
  let fails = read_int(store, "f:" + c.name)? + 1;
  if fails >= 3 {
    store.set("l:" + c.name, (now + 900000).to_str().to_bytes())?;
    store.delete("f:" + c.name)?;
  } else {
    store.set("f:" + c.name, fails.to_str().to_bytes())?;
  }
  Ok(reply(401, "bad credentials"))
}

fn me(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let token = match bearer(req) {
    Some(t) => t,
    None => return Ok(unauthorized()),
  };
  let now = clock.now_ms();
  let name = match session(store, token, now)? {
    Some(n) => n,
    None => return Ok(unauthorized()),
  };
  store.set("x:" + token, (now + 1800000).to_str().to_bytes())?;
  let logins = read_int(store, "n:" + name)?;
  Ok(Resp {
    status: 200,
    body: "{\"name\": \"" + name + "\", \"logins\": " + logins.to_str() + "}",
  })
}

fn logout(req: Incoming, store: Kv, clock: Clock) -> Result<Resp, KvErr> {
  let token = match bearer(req) {
    Some(t) => t,
    None => return Ok(unauthorized()),
  };
  let now = clock.now_ms();
  match session(store, token, now)? {
    Some(_) => {
      store.delete("s:" + token)?;
      store.delete("x:" + token)?;
      Ok(Resp { status: 204, body: "" })
    }
    None => Ok(unauthorized()),
  }
}

fn path_of(t: Str) -> Str {
  match t.find("?") {
    Some(i) => t.slice(0, i),
    None => t,
  }
}

fn route(req: Incoming, store: Kv, clock: Clock, rng: Rng) -> Result<Resp, KvErr> {
  let m = req.method();
  let p = path_of(req.target());
  if p == "/users" && m == "POST" {
    return create_user(req, store);
  }
  if p == "/login" && m == "POST" {
    return login(req, store, clock, rng);
  }
  if p == "/me" && m == "GET" {
    return me(req, store, clock);
  }
  if p == "/logout" && m == "POST" {
    return logout(req, store, clock);
  }
  Ok(reply(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, WebErr> {
  let r = match route(req, store, clock, rng) {
    Ok(v) => v,
    Err(_) => reply(500, "store error"),
  };
  let no_h: List<Str> = [];
  if r.status == 204 {
    res.send(204, no_h, no_h, "".to_bytes())?;
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  }
  Ok("ok")
}

struct Pay { id: Int, account: Str, cents: Int, currency: Str, status: Str, refunded: Int }

struct NewPay { account: Str, cents: Int, currency: Str }

struct Resp { status: Int, body: Str }

fn resp(status: Int, body: Str) -> Resp {
  Resp { status: status, body: body }
}

fn err_body(msg: Str) -> Str {
  "{\"error\": \"" + msg + "\"}"
}

fn not_found() -> Resp {
  resp(404, err_body("not found"))
}

fn sv_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(i) => i,
    _ => 0,
  }
}

fn sv_str(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn row_pay(r: List<SqlValue>) -> Pay {
  Pay {
    id: sv_int(r[0]),
    account: sv_str(r[1]),
    cents: sv_int(r[2]),
    currency: sv_str(r[3]),
    status: sv_str(r[4]),
    refunded: sv_int(r[5]),
  }
}

fn pay_json(p: Pay) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + p.id.to_str()));
  m.insert("account", Json::Str(p.account));
  m.insert("cents", Json::Num(p.cents));
  m.insert("currency", Json::Str(p.currency));
  m.insert("status", Json::Str(p.status));
  m.insert("refunded", Json::Num(p.refunded));
  let j = Json::Obj(m);
  j.to_json()
}

fn schema(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  Ok(())
}

fn load(db: Db, id: Int) -> Result<Option<Pay>, DbErr> {
  let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 {
    return Ok(None);
  }
  Ok(Some(row_pay(rows[0])))
}

fn parse_id(s: Str) -> Option<Int> {
  let rest = s.strip_prefix("pay_")?;
  rest.parse_int()
}

fn account_of(q: Str) -> Option<Str> {
  for kv in q.split("&") {
    if let Some(a) = kv.strip_prefix("account=") {
      return Some(a);
    }
  }
  None
}

fn idem_key(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == "idempotency-key" {
      return Some(values[i]);
    }
  }
  None
}

fn canonical(body: Str) -> Str {
  match body.parse_json() {
    Ok(j) => j.to_json(),
    Err(_) => body,
  }
}

fn lookup(db: Db, key: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
  if rows.len() == 0 {
    return Ok(None);
  }
  let r = rows[0];
  if sv_str(r[0]) != method || sv_str(r[1]) != path || sv_str(r[2]) != canon {
    return Ok(Some(resp(409, err_body("key reused"))));
  }
  Ok(Some(resp(sv_int(r[3]), sv_str(r[4]))))
}

fn remember(db: Db, key: Str, method: Str, path: Str, canon: Str, r: Resp) -> Result<Resp, DbErr> {
  if r.status >= 200 && r.status < 300 {
    db.exec("INSERT OR IGNORE INTO idem (key, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)", [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon), SqlValue::Int(r.status), SqlValue::Text(r.body)])?;
  }
  Ok(r)
}

fn parse_new(body: Str) -> Option<NewPay> {
  let j = body.parse_json().ok()?;
  let m = j.as_map()?;
  if m.len() != 3 {
    return None;
  }
  let account = m.get("account")?.as_str()?;
  let cents = m.get("cents")?.as_int()?;
  let currency = m.get("currency")?.as_str()?;
  if account == "" || cents <= 0 {
    return None;
  }
  if currency != "EUR" && currency != "USD" {
    return None;
  }
  Some(NewPay { account: account, cents: cents, currency: currency })
}

fn parse_refund(body: Str) -> Option<Int> {
  let j = body.parse_json().ok()?;
  let m = j.as_map()?;
  let c = m.get("cents")?.as_int()?;
  if c > 0 {
    Some(c)
  } else {
    None
  }
}

fn create_payment(db: Db, body: Str) -> Result<Resp, DbErr> {
  let Some(p) = parse_new(body) else {
    return Ok(resp(422, err_body("invalid payment")));
  };
  let rows = db.query("INSERT INTO payments (account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0) RETURNING id", [SqlValue::Text(p.account), SqlValue::Int(p.cents), SqlValue::Text(p.currency)])?;
  let id = sv_int(rows[0][0]);
  Ok(resp(201, pay_json(Pay { id: id, account: p.account, cents: p.cents, currency: p.currency, status: "pending", refunded: 0 })))
}

fn get_pay(db: Db, id: Int) -> Result<Resp, DbErr> {
  match load(db, id)? {
    None => Ok(not_found()),
    Some(p) => Ok(resp(200, pay_json(p))),
  }
}

fn list_pays(db: Db, account: Str) -> Result<Resp, DbErr> {
  let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY id", [SqlValue::Text(account)])?;
  let mut parts: List<Str> = [];
  for r in rows {
    parts.push(pay_json(row_pay(r)));
  }
  Ok(resp(200, "[" + parts.join(",") + "]"))
}

fn capture(db: Db, id: Int) -> Result<Resp, DbErr> {
  match load(db, id)? {
    None => Ok(not_found()),
    Some(p) => {
      if p.status == "captured" {
        return Ok(resp(200, pay_json(p)));
      }
      if p.status != "pending" {
        return Ok(resp(409, err_body("invalid transition")));
      }
      db.exec("UPDATE payments SET status = 'captured' WHERE id = ?", [SqlValue::Int(id)])?;
      Ok(resp(200, pay_json(Pay { status: "captured", ..p })))
    }
  }
}

fn cancel(db: Db, id: Int) -> Result<Resp, DbErr> {
  match load(db, id)? {
    None => Ok(not_found()),
    Some(p) => {
      if p.status != "pending" {
        return Ok(resp(409, err_body("invalid transition")));
      }
      db.exec("UPDATE payments SET status = 'canceled' WHERE id = ?", [SqlValue::Int(id)])?;
      Ok(resp(200, pay_json(Pay { status: "canceled", ..p })))
    }
  }
}

fn refund(db: Db, id: Int, cents: Int) -> Result<Resp, DbErr> {
  match load(db, id)? {
    None => Ok(not_found()),
    Some(p) => {
      if p.status != "captured" {
        return Ok(resp(409, err_body("invalid transition")));
      }
      if p.refunded + cents > p.cents {
        return Ok(resp(409, err_body("exceeds captured")));
      }
      let total = p.refunded + cents;
      let status = if total == p.cents { "refunded" } else { "captured" };
      db.exec("UPDATE payments SET refunded = ?, status = ? WHERE id = ?", [SqlValue::Int(total), SqlValue::Text(status), SqlValue::Int(id)])?;
      Ok(resp(200, pay_json(Pay { status: status, refunded: total, ..p })))
    }
  }
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  schema(db)?;
  let method = req.method();
  let parts = req.target().split("?");
  let path = parts[0];
  let query = if parts.len() > 1 { parts[1] } else { "" };
  let segs = path.split("/");
  let n = segs.len();

  if path == "/payments" && method == "POST" {
    let Some(k) = idem_key(req) else {
      return Ok(resp(400, err_body("missing idempotency key")));
    };
    let body = req.body().to_str();
    let canon = canonical(body);
    if let Some(old) = lookup(db, k, method, path, canon)? {
      return Ok(old);
    }
    let r = create_payment(db, body)?;
    return remember(db, k, method, path, canon, r);
  }

  if path == "/payments" && method == "GET" {
    let Some(account) = account_of(query) else {
      return Ok(not_found());
    };
    return list_pays(db, account);
  }

  if n == 3 && segs[1] == "payments" && method == "GET" {
    let Some(id) = parse_id(segs[2]) else {
      return Ok(not_found());
    };
    return get_pay(db, id);
  }

  if n == 4 && segs[1] == "payments" && method == "POST" && segs[3] == "capture" {
    let Some(id) = parse_id(segs[2]) else {
      return Ok(not_found());
    };
    return capture(db, id);
  }

  if n == 4 && segs[1] == "payments" && method == "POST" && segs[3] == "cancel" {
    let Some(id) = parse_id(segs[2]) else {
      return Ok(not_found());
    };
    return cancel(db, id);
  }

  if n == 4 && segs[1] == "payments" && method == "POST" && segs[3] == "refund" {
    let Some(k) = idem_key(req) else {
      return Ok(resp(400, err_body("missing idempotency key")));
    };
    let body = req.body().to_str();
    let canon = canonical(body);
    if let Some(old) = lookup(db, k, method, path, canon)? {
      return Ok(old);
    }
    let Some(amount) = parse_refund(body) else {
      return Ok(resp(422, err_body("invalid refund")));
    };
    let Some(id) = parse_id(segs[2]) else {
      return Ok(not_found());
    };
    let r = refund(db, id, amount)?;
    return remember(db, k, method, path, canon, r);
  }

  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let out = match handle(req, db) {
    Ok(r) => r,
    Err(_) => resp(500, err_body("internal")),
  };
  match res.send(out.status, ["content-type"], ["application/json"], out.body.to_bytes()) {
    Ok(_) => "sent",
    Err(_) => "send failed",
  }
}

// Sessions from a click log.

fn digits(b: Bytes, from: Int, to: Int) -> Bool {
  let mut i = from;
  let mut ok = true;
  while i < to {
    if b[i] < 48 || b[i] > 57 { ok = false; }
    i += 1;
  }
  ok
}

fn num(b: Bytes, from: Int, to: Int) -> Int {
  let mut v = 0;
  let mut i = from;
  while i < to {
    v = v * 10 + b[i] - 48;
    i += 1;
  }
  v
}

// Days since a fixed epoch (proleptic Gregorian). Years are shifted by 400
// so every intermediate value is non-negative; differences are unaffected.
fn days(y0: Int, m: Int, d: Int) -> Int {
  let y = if m <= 2 { y0 + 399 } else { y0 + 400 };
  let era = y / 400;
  let yoe = y - era * 400;
  let mp = if m > 2 { m - 3 } else { m + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  era * 146097 + doe
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  if !digits(b, 0, 4) || !digits(b, 5, 7) || !digits(b, 8, 10)
    || !digits(b, 11, 13) || !digits(b, 14, 16) || !digits(b, 17, 19) {
    return None;
  }
  let y = num(b, 0, 4);
  let mo = num(b, 5, 7);
  let d = num(b, 8, 10);
  let h = num(b, 11, 13);
  let mi = num(b, 14, 16);
  let se = num(b, 17, 19);
  if mo < 1 || mo > 12 { return None; }
  let leap = y % 4 == 0 && (y % 100 != 0 || y % 400 == 0);
  let mdays = if mo == 2 {
    if leap { 29 } else { 28 }
  } else if mo == 4 || mo == 6 || mo == 9 || mo == 11 {
    30
  } else {
    31
  };
  if d < 1 || d > mdays { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  Some(days(y, mo, d) * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(s: Int) -> Str {
  pad2(s / 3600) + ":" + pad2((s % 3600) / 60) + ":" + pad2(s % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();

  // A line identical to an earlier non-blank line is a duplicate.
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut users: Map<Str, List<Int>> = Map::new();
  // user -> (page -> event count); its length is the user's distinct pages.
  let mut pages: Map<Str, Map<Str, Int>> = Map::new();
  // page -> event count over all users.
  let mut pc: Map<Str, Int> = Map::new();
  let mut malformed = 0;
  let mut dups = 0;
  let mut valid = 0;

  for line in text.lines() {
    if line.trim() == "" { continue; }
    if seen.get(line).is_some() {
      dups += 1;
      continue;
    }
    seen.insert(line, true);

    let parts = line.split(" ");
    if parts.len() != 3 {
      malformed += 1;
      continue;
    }
    let Some(t) = parse_time(parts[0]) else {
      malformed += 1;
      continue;
    };
    let user = parts[1];
    let page = parts[2];
    valid += 1;

    let mut ts: List<Int> = match users.get(user) {
      Some(v) => v,
      None => [],
    };
    ts.push(t);
    users.insert(user, ts);

    let mut pg: Map<Str, Int> = match pages.get(user) {
      Some(v) => v,
      None => Map::new(),
    };
    let c = match pg.get(page) {
      Some(n) => n,
      None => 0,
    };
    pg.insert(page, c + 1);
    pages.insert(user, pg);

    let pcount = match pc.get(page) {
      Some(n) => n,
      None => 0,
    };
    pc.insert(page, pcount + 1);
  }

  let mut out: List<Str> = [];
  let mut durs: List<Int> = [];

  // Users in byte order (Map keys are sorted).
  for u in users.keys() {
    let mut ts: List<Int> = match users.get(u) {
      Some(v) => v,
      None => [],
    };
    ts.sort();
    let n = ts.len();
    let mut count = 1;
    let mut longest = 0;
    let mut start = ts[0];
    let mut prev = ts[0];
    for i in 1..n {
      let t = ts[i];
      if t - prev > 1800 {
        let d = prev - start;
        durs.push(d);
        if d > longest { longest = d; }
        start = t;
        count += 1;
      }
      prev = t;
    }
    let d = prev - start;
    durs.push(d);
    if d > longest { longest = d; }

    let pg: Map<Str, Int> = match pages.get(u) {
      Some(v) => v,
      None => Map::new(),
    };
    out.push(u + " sessions " + count.to_str() + " events " + n.to_str()
      + " longest " + hms(longest) + " pages " + pg.len().to_str());
  }

  if valid > 0 {
    let mut sorted = durs;
    sorted.sort();
    let m = sorted.len();
    let median = sorted[(m - 1) / 2];
    out.push("median " + median.to_str());

    // Pages by event count, most first; ties in byte order (stable sort).
    let mut plist = pc.keys();
    plist.sort_by(|a, b| pc.get(a).unwrap_or(0) > pc.get(b).unwrap_or(0));
    let k = if plist.len() < 3 { plist.len() } else { 3 };
    let mut tops: List<Str> = [];
    for i in 0..k {
      let p = plist[i];
      tops.push(p + " (" + pc.get(p).unwrap_or(0).to_str() + ")");
    }
    out.push("top: " + tops.join(", "));
  }

  out.push("malformed " + malformed.to_str() + " duplicates " + dups.to_str());
  Ok(out.join("\n"))
}

const LF: Int = 10;
const CR: Int = 13;
const QUOTE: Int = 34;
const COMMA: Int = 44;
const START: Int = 0;
const PLAIN: Int = 1;
const QUOTED: Int = 2;
const CLOSED: Int = 3;
const JUNK: Int = 4;

struct Rec { bad: Bool, fields: List<Bytes> }
struct Good { region: Str, product: Str, qty: Int, qty_s: Str, cents: Int, note: Str }

// Splits the file into records (RFC 4180, LF or CRLF ends a record).
// Blank lines between records are skipped. A record is marked bad when a
// quote is misplaced or a quoted field is still open at the end of the file.
fn parse(bs: Bytes) -> List<Rec> {
  let n = bs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Bytes> = [];
  let mut cur = "".to_bytes();
  let mut mode = START;
  let mut bad = false;
  let mut open = false;
  let mut i = 0;
  while i < n {
    let c = bs[i];
    let crlf = c == CR && i + 1 < n && bs[i + 1] == LF;
    if !open && c == LF { i += 1; continue; }
    if !open && crlf { i += 2; continue; }
    open = true;
    let mut field_end = false;
    let mut ends = false;
    if mode == QUOTED {
      if c == QUOTE {
        if i + 1 < n && bs[i + 1] == QUOTE {
          cur.push(QUOTE);
          i += 2;
        } else {
          mode = CLOSED;
          i += 1;
        }
      } else {
        cur.push(c);
        i += 1;
      }
    } else if c == LF || crlf {
      ends = true;
      if c == LF { i += 1; } else { i += 2; }
    } else if c == COMMA {
      field_end = true;
      i += 1;
    } else if mode == CLOSED {
      bad = true;
      mode = JUNK;
    } else if mode == JUNK {
      i += 1;
    } else if mode == START && c == QUOTE {
      mode = QUOTED;
      i += 1;
    } else {
      if c == QUOTE || c == CR { bad = true; }
      cur.push(c);
      mode = PLAIN;
      i += 1;
    }
    if field_end {
      fields.push(cur);
      cur = "".to_bytes();
      mode = START;
    }
    if ends {
      fields.push(cur);
      recs.push(Rec { bad: bad, fields: fields });
      fields = [];
      cur = "".to_bytes();
      mode = START;
      bad = false;
      open = false;
    }
  }
  if open {
    if mode == QUOTED { bad = true; }
    fields.push(cur);
    recs.push(Rec { bad: bad, fields: fields });
  }
  recs
}

fn all_digits(b: Bytes) -> Bool {
  if b.len() == 0 { return false; }
  for c in b {
    if c < 48 || c > 57 { return false; }
  }
  true
}

// An optional '-', then digits.
fn parse_qty(b: Bytes) -> Option<Int> {
  let digits = if b.len() > 0 && b[0] == 45 { b.slice(1, b.len()) } else { b };
  if !all_digits(digits) { return None; }
  b.to_str().parse_int()
}

// Digits, optionally '.' and one or two digits. Returns cents.
fn price_cents(b: Bytes) -> Option<Int> {
  let n = b.len();
  let mut dot = n;
  for k in 0..n {
    if b[k] == 46 && dot == n { dot = k; }
  }
  let ip = b.slice(0, dot);
  if !all_digits(ip) { return None; }
  let whole = ip.to_str().parse_int()?;
  if whole > 92233720368547758 { return None; }
  if dot == n { return Some(whole * 100); }
  let fb = b.slice(dot + 1, n);
  if !all_digits(fb) { return None; }
  if fb.len() == 1 { return Some(whole * 100 + (fb[0] - 48) * 10); }
  if fb.len() == 2 { return Some(whole * 100 + (fb[0] - 48) * 10 + (fb[1] - 48)); }
  None
}

// qty * cents must fit in an Int.
fn fits(qty: Int, cents: Int) -> Bool {
  if cents == 0 { return true; }
  let lim = 9223372036854775807 / cents;
  qty <= lim && qty >= 0 - lim
}

fn check(rec: Rec) -> Option<Good> {
  if rec.bad || rec.fields.len() != 5 { return None; }
  let f = rec.fields;
  if f[0].len() == 0 || f[1].len() == 0 { return None; }
  let qty = parse_qty(f[2])?;
  let cents = price_cents(f[3])?;
  if !fits(qty, cents) { return None; }
  Some(Good {
    region: f[0].to_str(),
    product: f[1].to_str(),
    qty: qty,
    qty_s: f[2].to_str(),
    cents: cents,
    note: f[4].to_str(),
  })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

// Cents as "R.CC", with a leading "-" when negative.
fn money(c: Int) -> Str {
  let a = if c < 0 { 0 - c } else { c };
  let w = a / 100;
  let s = w.to_str() + "." + pad2(a % 100);
  if c < 0 { "-" + s } else { s }
}

// One CSV field, quoted exactly when it holds a comma, quote, CR or LF.
fn csv_field(s: Str) -> Bytes {
  let b = s.to_bytes();
  let mut need = false;
  for c in b {
    if c == QUOTE || c == COMMA || c == CR || c == LF { need = true; }
  }
  let mut out = "".to_bytes();
  if need { out.push(QUOTE); }
  for c in b {
    if c == QUOTE { out.push(QUOTE); }
    out.push(c);
  }
  if need { out.push(QUOTE); }
  out
}

// One CSV record ending with LF.
fn row(fs: List<Str>) -> Bytes {
  let mut out = "".to_bytes();
  let mut first = true;
  for f in fs {
    if !first { out.push(COMMA); }
    first = false;
    out.extend(csv_field(f));
  }
  out.push(LF);
  out
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let bs = input.read("sales.csv")?;
  let recs = parse(bs);
  let n = if recs.len() > 0 { recs.len() - 1 } else { 0 };

  let mut buf = row(["region", "product", "qty", "price", "note"]);
  let mut reg_rev: Map<Str, Int> = Map::new();
  let mut reg_qty: Map<Str, Int> = Map::new();
  let mut prod_rev: Map<Str, Map<Str, Int>> = Map::new();
  let mut bad: List<Str> = [];
  let mut nbad = 0;

  // recs[0] is the header; recs[k] is data record k.
  for k in 1..recs.len() {
    match check(recs[k]) {
      Some(g) => {
        let rev = g.qty * g.cents;
        let rt = reg_rev.get(g.region).unwrap_or(0) + rev;
        reg_rev.insert(g.region, rt);
        let qt = reg_qty.get(g.region).unwrap_or(0) + g.qty;
        reg_qty.insert(g.region, qt);
        let mut inner: Map<Str, Int> = Map::new();
        if let Some(m) = prod_rev.get(g.region) { inner = m; }
        let pt = inner.get(g.product).unwrap_or(0) + rev;
        inner.insert(g.product, pt);
        prod_rev.insert(g.region, inner);
        buf.extend(row([g.region, g.product, g.qty_s, money(g.cents), g.note]));
      }
      None => {
        nbad += 1;
        bad.push(k.to_str());
      }
    }
  }

  let mut lines: List<Str> = [];
  for r in reg_rev.keys() {
    let rev = reg_rev.get(r).unwrap_or(0);
    let items = reg_qty.get(r).unwrap_or(0);
    let mut inner: Map<Str, Int> = Map::new();
    if let Some(m) = prod_rev.get(r) { inner = m; }
    let mut best = "";
    let mut best_v = 0;
    let mut first = true;
    for p in inner.keys() {
      let v = inner.get(p).unwrap_or(0);
      if first || v > best_v {
        best = p;
        best_v = v;
        first = false;
      }
    }
    lines.push(r + " revenue " + money(rev) + " items " + items.to_str() + " top " + best);
  }

  let tail = if nbad == 0 {
    "records " + n.to_str() + " bad 0"
  } else {
    "records " + n.to_str() + " bad " + nbad.to_str() + ": " + bad.join(", ")
  };
  lines.push(tail);

  out.write("clean.csv", buf)?;
  Ok(lines.join("\n"))
}

struct Change { path: Str, kind: Str }

fn io_msg(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "io: not found",
    IoErr::Denied => "io: denied",
    IoErr::TooLarge => "io: too large",
    IoErr::InvalidPath => "io: invalid path",
    IoErr::Exists => "io: exists",
  }
}

fn kv_msg(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv: too large",
    KvErr::Full => "kv: full",
    KvErr::NotInt => "kv: not an int",
    KvErr::Overflow => "kv: overflow",
  }
}

fn child(dir: Str, name: Str) -> Str {
  if dir.len() == 0 { name } else { dir + "/" + name }
}

fn walk(d: Dir, dir: Str, acc: List<Str>) -> Result<List<Str>, Str> {
  let mut out = acc;
  let names = d.list(dir).map_err(io_msg)?;
  for name in names {
    if name.ends_with("/") {
      out = walk(d, child(dir, name.slice(0, name.len() - 1)), out)?;
    } else {
      out.push(child(dir, name));
    }
  }
  Ok(out)
}

fn is_word(b: Int) -> Bool {
  (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || b >= 128
}

fn words(text: Bytes) -> List<Str> {
  let mut out: List<Str> = [];
  let mut cur: Bytes = "".to_bytes();
  for b in text {
    if is_word(b) {
      cur.push(b);
    } else if cur.len() > 0 {
      out.push(cur.to_str().to_lowercase());
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 {
    out.push(cur.to_str().to_lowercase());
  }
  out
}

fn word_set(text: Bytes) -> List<Str> {
  let mut seen: Map<Str, Int> = Map::new();
  for w in words(text) {
    if seen.get(w).is_none() {
      seen.insert(w, 1);
    }
  }
  seen.keys()
}

fn word_key(w: Str) -> Str { "w:" + w.sha256().to_hex() }

fn rec_key(p: Str) -> Str { "f:" + p.sha256().to_hex() }

fn posting(index: Kv, w: Str) -> Result<List<Str>, Str> {
  let mut out: List<Str> = [];
  if let Some(b) = index.get(word_key(w)).map_err(kv_msg)? {
    out = b.to_str().lines();
  }
  Ok(out)
}

fn put_posting(index: Kv, w: Str, paths: List<Str>) -> Result<(), Str> {
  if paths.len() == 0 {
    index.delete(word_key(w)).map_err(kv_msg)
  } else {
    index.set(word_key(w), paths.join("\n").to_bytes()).map_err(kv_msg)
  }
}

fn add_path(index: Kv, w: Str, p: Str) -> Result<(), Str> {
  let mut paths = posting(index, w)?;
  if paths.contains(p) {
    return Ok(());
  }
  paths.push(p);
  paths.sort();
  put_posting(index, w, paths)
}

fn remove_path(index: Kv, w: Str, p: Str) -> Result<(), Str> {
  let paths = posting(index, w)?;
  let mut kept: List<Str> = [];
  for q in paths {
    if q != p {
      kept.push(q);
    }
  }
  put_posting(index, w, kept)
}

fn index_file(index: Kv, p: Str, hash: Str, ws: List<Str>) -> Result<(), Str> {
  let mut parts: List<Str> = [p, hash];
  for w in ws {
    parts.push(w);
  }
  index.set(rec_key(p), parts.join("\n").to_bytes()).map_err(kv_msg)?;
  for w in ws {
    add_path(index, w, p)?;
  }
  Ok(())
}

fn unindex_rec(index: Kv, rec: Str) -> Result<(), Str> {
  let ls = rec.lines();
  let p = ls[0];
  for w in ls.slice(2, ls.len()) {
    remove_path(index, w, p)?;
  }
  index.delete(rec_key(p)).map_err(kv_msg)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let empty: List<Str> = [];
  let mut paths = walk(docs, "", empty)?;
  paths.sort();

  let mut now: Map<Str, Int> = Map::new();
  for p in paths {
    now.insert(p, 1);
  }

  let keys = index.keys("f:").map_err(kv_msg)?;
  let mut old: List<Str> = [];
  for k in keys {
    if let Some(b) = index.get(k).map_err(kv_msg)? {
      old.push(b.to_str());
    }
  }

  let mut changes: List<Change> = [];
  let mut before: Map<Str, Str> = Map::new();
  for rec in old {
    let ls = rec.lines();
    let p = ls[0];
    if now.get(p).is_none() {
      unindex_rec(index, rec)?;
      changes.push(Change { path: p, kind: "removed" });
    } else {
      before.insert(p, rec);
    }
  }

  let mut unchanged = 0;
  for p in paths {
    let bytes = docs.read(p).map_err(io_msg)?;
    let hash = bytes.sha256().to_hex();
    match before.get(p) {
      Some(rec) => {
        let ls = rec.lines();
        if ls[1] == hash {
          unchanged = unchanged + 1;
        } else {
          unindex_rec(index, rec)?;
          index_file(index, p, hash, word_set(bytes))?;
          changes.push(Change { path: p, kind: "changed" });
        }
      }
      None => {
        index_file(index, p, hash, word_set(bytes))?;
        changes.push(Change { path: p, kind: "added" });
      }
    }
  }

  changes.sort_by_key(|c| c.path);

  let mut out: List<Str> = [];
  for c in changes {
    out.push(c.kind + " " + c.path);
  }
  out.push("unchanged " + unchanged.to_str());

  let text = queries.read("queries.txt").map_err(io_msg)?.to_str();
  for line in text.lines() {
    if line.trim().len() == 0 {
      continue;
    }
    let ws = words(line.to_bytes());
    if ws.len() == 0 {
      out.push(line + ": none");
      continue;
    }
    let mut hits: List<Str> = posting(index, ws[0])?;
    for w in ws.slice(1, ws.len()) {
      let ps = posting(index, w)?;
      let mut kept: List<Str> = [];
      for h in hits {
        if ps.contains(h) {
          kept.push(h);
        }
      }
      hits = kept;
    }
    if hits.len() == 0 {
      out.push(line + ": none");
    } else {
      out.push(line + ": " + hits.join(", "));
    }
  }

  Ok(out.join("\n"))
}

const UPSERT_SQL: Str = "INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0 WHERE excluded.version > items.version";
const DELETE_SQL: Str = "INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, deleted = 1 WHERE excluded.version > items.version";
const CURSOR_SQL: Str = "UPDATE sync_state SET cursor = ? WHERE id = 1";

struct Change { op: Str, sku: Str, name: Str, qty: Int, version: Int }
struct Page { changes: List<Json>, next: Option<Str> }

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn byte_in(b: Bytes, i: Int, lo: Int, hi: Int) -> Bool {
  i < b.len() && b[i] >= lo && b[i] <= hi
}

fn utf8_ok(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  let mut ok = true;
  while i < n && ok {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if byte_in(b, i + 1, 128, 191) { i += 2; } else { ok = false; }
    } else if c >= 224 && c <= 239 {
      let lo = if c == 224 { 160 } else { 128 };
      let hi = if c == 237 { 159 } else { 191 };
      if byte_in(b, i + 1, lo, hi) && byte_in(b, i + 2, 128, 191) { i += 3; } else { ok = false; }
    } else if c >= 240 && c <= 244 {
      let lo = if c == 240 { 144 } else { 128 };
      let hi = if c == 244 { 143 } else { 191 };
      if byte_in(b, i + 1, lo, hi) && byte_in(b, i + 2, 128, 191) && byte_in(b, i + 3, 128, 191) {
        i += 4;
      } else {
        ok = false;
      }
    } else {
      ok = false;
    }
  }
  ok
}

fn parse_change(j: Json) -> Option<Change> {
  let Some(opj) = j.get("op") else { return None; };
  let Some(op) = opj.as_str() else { return None; };
  let Some(skuj) = j.get("sku") else { return None; };
  let Some(sku) = skuj.as_str() else { return None; };
  let Some(vj) = j.get("version") else { return None; };
  let Some(version) = vj.as_int() else { return None; };
  if op == "delete" {
    return Some(Change { op: op, sku: sku, name: "", qty: 0, version: version });
  }
  if op != "upsert" { return None; }
  let Some(nj) = j.get("name") else { return None; };
  let Some(name) = nj.as_str() else { return None; };
  let Some(qj) = j.get("qty") else { return None; };
  let Some(qty) = qj.as_int() else { return None; };
  Some(Change { op: op, sku: sku, name: name, qty: qty, version: version })
}

fn parse_page(body: Bytes) -> Option<Page> {
  if !utf8_ok(body) { return None; }
  let Ok(doc) = body.to_str().parse_json() else { return None; };
  let Json::Obj(m) = doc else { return None; };
  let Some(cj) = m.get("changes") else { return None; };
  let Some(changes) = cj.as_list() else { return None; };
  let next: Option<Str> = match m.get("next") {
    Some(Json::Str(s)) => Some(s),
    Some(Json::Null) => None,
    _ => return None,
  };
  Some(Page { changes: changes, next: next })
}

fn fetch(api: Http, cur: Str) -> Result<Page, Str> {
  let Ok(r) = api.send("GET", "/changes?cursor=" + cur, [], "".to_bytes()) else {
    return Err("(no response)");
  };
  if r.status != 200 {
    return Err("(status " + r.status.to_str() + ")");
  }
  match parse_page(r.body) {
    Some(p) => Ok(p),
    None => Err("(invalid page)"),
  }
}

fn read_cursor(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT cursor FROM sync_state WHERE id = 1", [])?;
  Ok(text_of(rows[0][0]))
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS sync_state (id INTEGER PRIMARY KEY, cursor TEXT NOT NULL)", [])?;
  db.exec("INSERT OR IGNORE INTO sync_state (id, cursor) VALUES (1, '0')", [])?;

  let mut cur = read_cursor(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut stop = "";

  loop {
    let fetched = fetch(api, cur);
    if fetched.is_err() {
      stop = "stopped at " + cur + " " + fetched.err().unwrap_or("");
      break;
    }
    let page = match fetched {
      Ok(p) => p,
      Err(_) => break,
    };

    let mut sqls: List<Str> = [];
    let mut args: List<List<SqlValue>> = [];
    let mut valid = 0;
    for c in page.changes {
      let Some(ch) = parse_change(c) else {
        invalid += 1;
        continue;
      };
      if ch.op == "delete" {
        sqls.push(DELETE_SQL);
        args.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
      } else {
        sqls.push(UPSERT_SQL);
        args.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version)]);
      }
      valid += 1;
    }

    let next = page.next;
    let stored = match next {
      Some(s) => s,
      None => cur,
    };
    sqls.push(CURSOR_SQL);
    args.push([SqlValue::Text(stored)]);

    let total = db.transaction(sqls, args)?;
    let got = total - 1;
    applied += got;
    stale += valid - got;
    pages += 1;

    let Some(n) = next else {
      stop = "complete";
      break;
    };
    cur = n;
  }

  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(stop);

  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for row in rows {
    lines.push(text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + text_of(row[2]));
  }

  Ok(lines.join("\n"))
}

struct Job { id: Str, state: Str, attempts: Int, due: Int, priority: Int }

fn encode(j: Job) -> Str {
  j.state + " " + j.attempts.to_str() + " " + j.due.to_str() + " " + j.priority.to_str()
}

fn decode(id: Str, s: Str) -> Option<Job> {
  let p = s.split(" ");
  if p.len() != 4 { return None; }
  Some(Job { id: id, state: p[0], attempts: p[1].parse_int()?, due: p[2].parse_int()?, priority: p[3].parse_int()? })
}

fn parse_enqueue(line: Str, now: Int) -> Option<Job> {
  let j = line.parse_json().ok()?;
  let id = j.get("id")?.as_str()?;
  let priority = j.get("priority")?.as_int()?;
  Some(Job { id: id, state: "pending", attempts: 0, due: now, priority: priority })
}

// The outcome of attempt number `attempt` (0-based) of job `id`.
fn outcome(script: Json, id: Str, attempt: Int) -> Str {
  let mut items: List<Json> = [];
  if let Some(v) = script.get(id) {
    if let Some(l) = v.as_list() { items = l; }
  }
  if items.len() == 0 { return "ok"; }
  let mut k = attempt;
  if k >= items.len() { k = items.len() - 1; }
  match items[k].as_str() {
    Some(s) => s,
    None => "ok",
  }
}

// Highest priority first, then earliest due, then id.
fn runs_before(a: Job, b: Job) -> Bool {
  if a.priority != b.priority { return a.priority > b.priority; }
  if a.due != b.due { return a.due < b.due; }
  a.id < b.id
}

fn kv_get(queue: Kv, key: Str) -> Result<Option<Str>, Str> {
  match queue.get(key) {
    Ok(Some(b)) => Ok(Some(b.to_str())),
    Ok(None) => Ok(None),
    Err(_) => Err("queue read failed"),
  }
}

fn kv_set(queue: Kv, key: Str, val: Str) -> Result<(), Str> {
  match queue.set(key, val.to_bytes()) {
    Ok(_) => Ok(()),
    Err(_) => Err("queue write failed"),
  }
}

fn load_jobs(queue: Kv) -> Result<List<Job>, Str> {
  let keys = match queue.keys("job:") {
    Ok(ks) => ks,
    Err(_) => return Err("queue list failed"),
  };
  let mut jobs: List<Job> = [];
  for key in keys {
    let got = kv_get(queue, key)?;
    if let Some(s) = got {
      if let Some(j) = decode(key.slice(4, key.len()), s) { jobs.push(j); }
    }
  }
  Ok(jobs)
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut out = "";

  // Enqueue
  let text = match input.read("enqueue.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let lines = text.lines();
  for i in 0..lines.len() {
    let line = lines[i].trim();
    if line.len() == 0 { continue; }
    let n = i + 1;
    let Some(job) = parse_enqueue(line, now) else {
      out = out + "invalid line " + n.to_str() + "\n";
      continue;
    };
    let key = "job:" + job.id;
    let existing = kv_get(queue, key)?;
    if existing.is_some() {
      out = out + "duplicate " + job.id + "\n";
      continue;
    }
    kv_set(queue, key, encode(job))?;
  }

  // Work
  let script = match input.read("script.json") {
    Ok(b) => match b.to_str().parse_json() {
      Ok(j) => j,
      Err(_) => return Err("script.json is not JSON"),
    },
    Err(_) => Json::Null,
  };

  let all = load_jobs(queue)?;
  let mut ready: List<Job> = [];
  for j in all {
    if j.state == "pending" && j.due <= now { ready.push(j); }
  }
  ready.sort_by(runs_before);
  let take = if ready.len() < 5 { ready.len() } else { 5 };

  for i in 0..take {
    let job = ready[i];
    let res = outcome(script, job.id, job.attempts);
    let n = job.attempts + 1;
    if res == "fail" {
      if n == 4 {
        kv_set(queue, "job:" + job.id, encode(Job { state: "dead", attempts: n, ..job }))?;
        out = out + "dead " + job.id + "\n";
      } else {
        let secs = match n {
          1 => 60,
          2 => 120,
          _ => 240,
        };
        let next = Job { state: "pending", attempts: n, due: now + secs * 1000, ..job };
        kv_set(queue, "job:" + job.id, encode(next))?;
        out = out + "retry " + job.id + " in " + secs.to_str() + "\n";
      }
    } else {
      kv_set(queue, "job:" + job.id, encode(Job { state: "done", attempts: n, ..job }))?;
      out = out + "done " + job.id + "\n";
    }
  }

  // Summary
  let after = load_jobs(queue)?;
  let mut pending = 0;
  let mut done = 0;
  let mut dead = 0;
  for j in after {
    if j.state == "pending" {
      pending += 1;
    } else if j.state == "done" {
      done += 1;
    } else {
      dead += 1;
    }
  }
  out = out + "pending " + pending.to_str() + " done " + done.to_str() + " dead " + dead.to_str();
  Ok(out)
}

struct Binding { name: Str, value: Int }

struct Ev { val: Int, pos: Int }

fn hi() -> Int { 9223372036854775807 }

fn lo() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Str) -> Bool { c >= "0" && c <= "9" }

fn is_alpha(c: Str) -> Bool {
  (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c == "_"
}

fn is_word(c: Str) -> Bool { is_alpha(c) || is_digit(c) }

fn is_sym(c: Str) -> Bool {
  c == "+" || c == "-" || c == "*" || c == "/" || c == "%" || c == "^"
    || c == "(" || c == ")" || c == "=" || c == ","
}

fn is_add(s: Str) -> Bool { s == "+" || s == "-" }

fn is_mul(s: Str) -> Bool { s == "*" || s == "/" || s == "%" }

fn first_char(s: Str) -> Str {
  if s.len() == 0 { "" } else { s.slice(0, 1) }
}

fn is_num(s: Str) -> Bool { is_digit(first_char(s)) }

fn is_name(s: Str) -> Bool { is_alpha(first_char(s)) }

fn at(t: List<Str>, p: Int) -> Str {
  if p < t.len() { t[p] } else { "" }
}

fn tokenize(line: Str) -> List<Str> {
  let cs = line.chars();
  let n = cs.len();
  let mut toks: List<Str> = [];
  let mut i = 0;
  while i < n {
    let c = cs[i];
    if c == " " {
      i = i + 1;
    } else if is_digit(c) || is_alpha(c) {
      let digits = is_digit(c);
      let mut s = "";
      let mut j = i;
      while j < n {
        let d = cs[j];
        let ok = if digits { is_digit(d) } else { is_word(d) };
        if !ok { break; }
        s = s + d;
        j = j + 1;
      }
      toks.push(s);
      i = j;
    } else if is_sym(c) {
      toks.push(c);
      i = i + 1;
    } else {
      // never valid in the grammar, so the syntax check rejects the line
      toks.push("?");
      i = i + 1;
    }
  }
  toks
}

// ---- syntax pass: returns the position after the construct ----

fn sx_atom(t: List<Str>, p: Int) -> Result<Int, Str> {
  let tok = at(t, p);
  if is_num(tok) { return Ok(p + 1); }
  if is_name(tok) {
    if at(t, p + 1) != "(" { return Ok(p + 1); }
    let mut q = sx_expr(t, p + 2)?;
    while at(t, q) == "," {
      q = sx_expr(t, q + 1)?;
    }
    if at(t, q) != ")" { return Err("syntax error"); }
    return Ok(q + 1);
  }
  if tok == "(" {
    let q = sx_expr(t, p + 1)?;
    if at(t, q) != ")" { return Err("syntax error"); }
    return Ok(q + 1);
  }
  Err("syntax error")
}

fn sx_power(t: List<Str>, p: Int) -> Result<Int, Str> {
  let q = sx_atom(t, p)?;
  if at(t, q) == "^" { return sx_factor(t, q + 1); }
  Ok(q)
}

fn sx_factor(t: List<Str>, p: Int) -> Result<Int, Str> {
  if at(t, p) == "-" { return sx_factor(t, p + 1); }
  sx_power(t, p)
}

fn sx_term(t: List<Str>, p: Int) -> Result<Int, Str> {
  let mut q = sx_factor(t, p)?;
  while is_mul(at(t, q)) {
    q = sx_factor(t, q + 1)?;
  }
  Ok(q)
}

fn sx_expr(t: List<Str>, p: Int) -> Result<Int, Str> {
  let mut q = sx_term(t, p)?;
  while is_add(at(t, q)) {
    q = sx_term(t, q + 1)?;
  }
  Ok(q)
}

fn whole(t: List<Str>, p: Int) -> Bool {
  if let Ok(q) = sx_expr(t, p) { return q == t.len(); }
  false
}

fn syntax_ok(t: List<Str>) -> Bool {
  if at(t, 0) == "let" {
    if !is_name(at(t, 1)) { return false; }
    if at(t, 2) != "=" { return false; }
    return whole(t, 3);
  }
  whole(t, 0)
}

// ---- checked arithmetic (kio stops the run on overflow, so check first) ----

fn add_checked(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 {
    if a > hi() - b { return Err("overflow"); }
  }
  if b < 0 {
    if a < lo() - b { return Err("overflow"); }
  }
  Ok(a + b)
}

fn sub_checked(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 {
    if a < lo() + b { return Err("overflow"); }
  }
  if b < 0 {
    if a > hi() + b { return Err("overflow"); }
  }
  Ok(a - b)
}

fn neg_checked(a: Int) -> Result<Int, Str> {
  if a == lo() { return Err("overflow"); }
  Ok(0 - a)
}

fn abs_checked(a: Int) -> Result<Int, Str> {
  if a < 0 { return neg_checked(a); }
  Ok(a)
}

fn mul_checked(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if b == -1 { return neg_checked(a); }
  if a == -1 { return neg_checked(b); }
  // from here neither operand is 0 or -1, so the divisions below cannot overflow
  let bad = if a > 0 {
    if b > 0 { a > hi() / b } else { a > lo() / b }
  } else {
    if b > 0 { b > lo() / a } else { a < hi() / b }
  };
  if bad { return Err("overflow"); }
  Ok(a * b)
}

fn div_checked(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return neg_checked(a); }
  Ok(a / b)
}

fn rem_checked(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn pow_checked(a: Int, e: Int) -> Result<Int, Str> {
  if e < 0 { return Err("negative exponent"); }
  let mut result = 1;
  let mut base = a;
  let mut n = e;
  while n > 0 {
    if n % 2 == 1 {
      result = mul_checked(result, base)?;
    }
    n = n / 2;
    if n > 0 {
      base = mul_checked(base, base)?;
    }
  }
  Ok(result)
}

fn arith(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return add_checked(a, b); }
  if op == "-" { return sub_checked(a, b); }
  if op == "*" { return mul_checked(a, b); }
  if op == "/" { return div_checked(a, b); }
  rem_checked(a, b)
}

fn parse_lit(s: Str) -> Result<Int, Str> {
  let all = "0123456789";
  let mut acc = 0;
  for c in s.chars() {
    let d = all.find(c).unwrap_or(0);
    if acc > (hi() - d) / 10 { return Err("overflow"); }
    acc = acc * 10 + d;
  }
  Ok(acc)
}

fn lookup(env: List<Binding>, name: Str) -> Option<Int> {
  let mut found: Option<Int> = None;
  for b in env {
    if b.name == name { found = Some(b.value); }
  }
  found
}

// ---- evaluation pass (the syntax is already known to be valid) ----

fn count_args(t: List<Str>, q: Int) -> Result<Int, Str> {
  let mut n = 1;
  let mut r = sx_expr(t, q)?;
  while at(t, r) == "," {
    r = sx_expr(t, r + 1)?;
    n = n + 1;
  }
  Ok(n)
}

fn ev_call(t: List<Str>, name: Str, q: Int, env: List<Binding>) -> Result<Ev, Str> {
  if name != "min" && name != "max" && name != "abs" {
    return Err("unknown function " + name);
  }
  let want = if name == "abs" { 1 } else { 2 };
  let got = count_args(t, q)?;
  if got != want {
    return Err("wrong number of arguments to " + name);
  }
  let first = ev_expr(t, q, env)?;
  let mut vals: List<Int> = [first.val];
  let mut r = first.pos;
  while at(t, r) == "," {
    let nxt = ev_expr(t, r + 1, env)?;
    vals.push(nxt.val);
    r = nxt.pos;
  }
  let stop = r + 1;
  let x = vals[0];
  if name == "abs" {
    let a = abs_checked(x)?;
    return Ok(Ev { val: a, pos: stop });
  }
  let y = vals[1];
  if name == "min" { return Ok(Ev { val: x.min(y), pos: stop }); }
  Ok(Ev { val: x.max(y), pos: stop })
}

fn ev_atom(t: List<Str>, p: Int, env: List<Binding>) -> Result<Ev, Str> {
  let tok = at(t, p);
  if is_num(tok) {
    let v = parse_lit(tok)?;
    return Ok(Ev { val: v, pos: p + 1 });
  }
  if is_name(tok) {
    if at(t, p + 1) == "(" { return ev_call(t, tok, p + 2, env); }
    if let Some(v) = lookup(env, tok) { return Ok(Ev { val: v, pos: p + 1 }); }
    return Err("unknown variable " + tok);
  }
  let inner = ev_expr(t, p + 1, env)?;
  Ok(Ev { val: inner.val, pos: inner.pos + 1 })
}

fn ev_power(t: List<Str>, p: Int, env: List<Binding>) -> Result<Ev, Str> {
  let base = ev_atom(t, p, env)?;
  if at(t, base.pos) == "^" {
    let ex = ev_factor(t, base.pos + 1, env)?;
    let v = pow_checked(base.val, ex.val)?;
    return Ok(Ev { val: v, pos: ex.pos });
  }
  Ok(base)
}

fn ev_factor(t: List<Str>, p: Int, env: List<Binding>) -> Result<Ev, Str> {
  if at(t, p) == "-" {
    let f = ev_factor(t, p + 1, env)?;
    let v = neg_checked(f.val)?;
    return Ok(Ev { val: v, pos: f.pos });
  }
  ev_power(t, p, env)
}

fn ev_term(t: List<Str>, p: Int, env: List<Binding>) -> Result<Ev, Str> {
  let mut acc = ev_factor(t, p, env)?;
  while is_mul(at(t, acc.pos)) {
    let op = at(t, acc.pos);
    let rhs = ev_factor(t, acc.pos + 1, env)?;
    let v = arith(op, acc.val, rhs.val)?;
    acc = Ev { val: v, pos: rhs.pos };
  }
  Ok(acc)
}

fn ev_expr(t: List<Str>, p: Int, env: List<Binding>) -> Result<Ev, Str> {
  let mut acc = ev_term(t, p, env)?;
  while is_add(at(t, acc.pos)) {
    let op = at(t, acc.pos);
    let rhs = ev_term(t, acc.pos + 1, env)?;
    let v = arith(op, acc.val, rhs.val)?;
    acc = Ev { val: v, pos: rhs.pos };
  }
  Ok(acc)
}

fn eval_at(t: List<Str>, p: Int, env: List<Binding>) -> Result<Int, Str> {
  let r = ev_expr(t, p, env)?;
  Ok(r.val)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let lines = text.lines();
  let mut env: List<Binding> = [];
  let mut out: List<Str> = [];
  let mut n = 0;
  for line in lines {
    n = n + 1;
    let toks = tokenize(line);
    if toks.len() == 0 { continue; }
    let label = n.to_str() + ": ";
    if !syntax_ok(toks) {
      out.push(label + "error: syntax error");
      continue;
    }
    let is_let = at(toks, 0) == "let";
    let start = if is_let { 3 } else { 0 };
    match eval_at(toks, start, env) {
      Ok(v) => {
        if is_let {
          let name = at(toks, 1);
          env.push(Binding { name: name, value: v });
          out.push(label + name + " = " + v.to_str());
        } else {
          out.push(label + v.to_str());
        }
      }
      Err(e) => {
        out.push(label + "error: " + e);
      }
    }
  }
  Ok(out.join("\n"))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Str {
  finish(res, route(req, res, db, secrets, log))
}

fn finish(res: Outgoing, r: Result<Str, DbErr>) -> Str {
  match r {
    Ok(s) => s,
    Err(_) => reply(res, 500, "{\"error\": \"database\"}"),
  }
}

fn reply(res: Outgoing, status: Int, body: Str) -> Str {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes());
  body
}

fn invalid(res: Outgoing) -> Result<Str, DbErr> {
  Ok(reply(res, 400, "{\"error\": \"invalid event\"}"))
}

fn setup(db: Db) -> Result<Int, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS seen (id TEXT PRIMARY KEY)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS history (pos INTEGER PRIMARY KEY, sub TEXT NOT NULL, state TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS pending (sub TEXT NOT NULL, seq INTEGER NOT NULL, id TEXT NOT NULL, typ TEXT NOT NULL, PRIMARY KEY (sub, seq))", [])?;
  Ok(0)
}

fn route(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, DbErr> {
  setup(db)?;
  let method = req.method();
  let target = req.target();
  let path = match target.find("?") {
    Some(i) => target.slice(0, i),
    None => target,
  };
  if method == "POST" && path == "/webhooks" {
    return post_webhook(req, res, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      return get_subscription(res, db, id);
    }
  }
  Ok(reply(res, 404, "{\"error\": \"not found\"}"))
}

fn header_of(names: List<Str>, values: List<Str>, want: Str) -> Option<Str> {
  for i in 0..names.len() {
    if names[i] == want {
      return Some(values[i]);
    }
  }
  None
}

fn strip_newline(raw: Bytes) -> Bytes {
  let n = raw.len();
  if n > 0 && raw[n - 1] == 10 {
    return raw.slice(0, n - 1);
  }
  raw
}

fn known(t: Str) -> Bool {
  t == "subscription.created"
    || t == "subscription.activated"
    || t == "payment.failed"
    || t == "subscription.canceled"
}

fn next_state(event: Str, from: Str) -> Option<Str> {
  if event == "subscription.created" && from == "none" {
    return Some("created");
  }
  if event == "subscription.activated" && (from == "created" || from == "past_due") {
    return Some("active");
  }
  if event == "payment.failed" && from == "active" {
    return Some("past_due");
  }
  if event == "subscription.canceled" && (from == "created" || from == "active" || from == "past_due") {
    return Some("canceled");
  }
  None
}

fn cell_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn cell_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn remember(db: Db, id: Str) -> Result<Int, DbErr> {
  db.exec("INSERT OR IGNORE INTO seen (id) VALUES (?)", [SqlValue::Text(id)])
}

fn last_seq(db: Db, sub: Str) -> Result<Int, DbErr> {
  let rows = db.query("SELECT seq FROM subs WHERE id = ?", [SqlValue::Text(sub)])?;
  if rows.len() == 0 {
    return Ok(0);
  }
  Ok(cell_int(rows[0][0]))
}

// Applies one event whose seq is the next expected one.
fn apply(db: Db, log: Log, sub: Str, id: Str, typ: Str, seq: Int) -> Result<Int, DbErr> {
  let rows = db.query("SELECT state FROM subs WHERE id = ?", [SqlValue::Text(sub)])?;
  let mut state = "none";
  if rows.len() > 0 {
    state = cell_text(rows[0][0]);
  }
  let nx = next_state(typ, state);
  let mut new_state = state;
  match nx {
    Some(s) => {
      new_state = s;
      db.exec("INSERT INTO history (sub, state) VALUES (?, ?)", [SqlValue::Text(sub), SqlValue::Text(s)])?;
    },
    None => {
      log.write("invalid transition " + id);
    },
  }
  db.exec("INSERT OR REPLACE INTO subs (id, state, seq) VALUES (?, ?, ?)", [SqlValue::Text(sub), SqlValue::Text(new_state), SqlValue::Int(seq)])?;
  Ok(0)
}

// Applies kept events that now follow in sequence; returns how many.
fn drain(db: Db, log: Log, sub: Str, last: Int) -> Result<Int, DbErr> {
  let mut at = last;
  let mut count = 0;
  loop {
    let rows = db.query("SELECT id, typ FROM pending WHERE sub = ? AND seq = ?", [SqlValue::Text(sub), SqlValue::Int(at + 1)])?;
    if rows.len() == 0 {
      break;
    }
    let pid = cell_text(rows[0][0]);
    let ptyp = cell_text(rows[0][1]);
    db.exec("DELETE FROM pending WHERE sub = ? AND seq = ?", [SqlValue::Text(sub), SqlValue::Int(at + 1)])?;
    apply(db, log, sub, pid, ptyp, at + 1)?;
    at = at + 1;
    count = count + 1;
  }
  Ok(count)
}

fn post_webhook(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, DbErr> {
  let Ok(raw) = secrets.read("webhook.key") else {
    return Ok(reply(res, 500, "{\"error\": \"server\"}"));
  };
  let mut msg = strip_newline(raw);
  msg.push(46);
  let body = req.body();
  msg.extend(body);
  let sig = match header_of(req.header_names(), req.header_values(), "x-signature") {
    Some(s) => s,
    None => "",
  };
  let expected = "sha256=" + msg.sha256().to_hex();
  if !sig.ct_eq(expected) {
    log.write("rejected signature");
    return Ok(reply(res, 401, "{\"error\": \"bad signature\"}"));
  }

  let Ok(j) = req.body().to_str().parse_json() else {
    return invalid(res);
  };
  let Some(id) = j.get("id").and_then(|v| v.as_str()) else { return invalid(res); };
  let Some(typ) = j.get("type").and_then(|v| v.as_str()) else { return invalid(res); };
  let Some(sub) = j.get("subscription").and_then(|v| v.as_str()) else { return invalid(res); };
  let Some(seq) = j.get("seq").and_then(|v| v.as_int()) else { return invalid(res); };
  if seq < 1 || !known(typ) {
    return invalid(res);
  }

  let seen = db.query("SELECT 1 FROM seen WHERE id = ?", [SqlValue::Text(id)])?;
  if seen.len() > 0 {
    return Ok(reply(res, 200, "{\"status\": \"duplicate\"}"));
  }

  let last = last_seq(db, sub)?;
  if seq <= last {
    remember(db, id)?;
    return Ok(reply(res, 200, "{\"status\": \"stale\"}"));
  }
  if seq > last + 1 {
    remember(db, id)?;
    db.exec("INSERT OR IGNORE INTO pending (sub, seq, id, typ) VALUES (?, ?, ?, ?)", [SqlValue::Text(sub), SqlValue::Int(seq), SqlValue::Text(id), SqlValue::Text(typ)])?;
    return Ok(reply(res, 202, "{\"status\": \"queued\"}"));
  }

  remember(db, id)?;
  apply(db, log, sub, id, typ, seq)?;
  let more = drain(db, log, sub, seq)?;
  Ok(reply(res, 200, "{\"status\": \"applied\", \"applied\": " + (more + 1).to_str() + "}"))
}

fn get_subscription(res: Outgoing, db: Db, id: Str) -> Result<Str, DbErr> {
  let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [SqlValue::Text(id)])?;
  if rows.len() == 0 {
    return Ok(reply(res, 404, "{\"error\": \"not found\"}"));
  }
  let state = cell_text(rows[0][0]);
  let seq = cell_int(rows[0][1]);
  let hist = db.query("SELECT state FROM history WHERE sub = ? ORDER BY pos", [SqlValue::Text(id)])?;
  let mut hs: List<Json> = [];
  for h in hist {
    hs.push(Json::Str(cell_text(h[0])));
  }
  let id_json = Json::Str(id).to_json();
  let state_json = Json::Str(state).to_json();
  let hist_json = Json::Arr(hs).to_json();
  Ok(reply(res, 200, "{\"id\": " + id_json + ", \"state\": " + state_json + ", \"seq\": " + seq.to_str() + ", \"history\": " + hist_json + "}"))
}
